// core/data/connections.js — grouping puzzles for QUARTETS (window.AD_CONNECTIONS).
// Source: hand-authored for this arcade (_build/conn_*.py). Generated by _build/gen_connections.py — do not edit by hand.
// Colours y<g<b<p ascend in difficulty. Every board is verified uniquely solvable; see the trap table in the generator's report.
window.AD_CONNECTIONS = {
"packs":[
{"id":"general","name":"MIXED BAG","blurb":"The main archive. Wordplay, general knowledge, and a purple that bites.","boards":[
{"id":1,"title":"Warm-Up","diff":1,"groups":[{"name":"CITRUS FRUITS","colour":"y","tiles":["LEMON","LIME","ORANGE","POMELO"],"note":"The pomelo is the big one — grapefruit is its child, a pomelo crossed with a sweet orange."},{"name":"SHADES OF BLUE","colour":"g","tiles":["NAVY","COBALT","AZURE","INDIGO"],"note":"Cobalt from the ore, azure from lapis lazuli, indigo from the plant, navy from the Royal Navy's 1748 uniform."},{"name":"___ BALL","colour":"b","tiles":["CRYSTAL","ODD","MEAT","SNOW"],"note":"Crystal ball, oddball, meatball, snowball. Four very different evenings."},{"name":"ANIMALS HIDING INSIDE","colour":"p","tiles":["POTTERY","CRATER","SHAPELY","PROWLER"],"note":"p-OTTER-y, c-RAT-er, sh-APE-ly, pr-OWL-er. You will never read them normally again."}],"epilogue":"A gentle one to calibrate on. If you spent a while looking for a fifth citrus, that's the shape of every board from here: the trick is never the words you know, it's the ones you're sure about."},
{"id":2,"title":"Kitchen Sink","diff":1,"groups":[{"name":"PASTA SHAPES","colour":"y","tiles":["PENNE","FUSILLI","RIGATONI","ORZO"],"note":"Penne means 'quills', fusilli 'little spindles', rigatoni 'ridged'. Orzo means 'barley', which it isn't."},{"name":"KITCHEN UTENSILS","colour":"g","tiles":["SPATULA","WHISK","LADLE","TONGS"],"note":"The four things every drawer has three of and you can never find one."},{"name":"___ PAPER","colour":"b","tiles":["WALL","NEWS","SAND","WASTE"],"note":"Wallpaper, newspaper, sandpaper, wastepaper. Two of them are basically extinct."},{"name":"READ THEM BACKWARDS","colour":"p","tiles":["DIAPER","LAGER","STRAW","DESSERTS"],"note":"Repaid, regal, warts, stressed. DESSERTS/STRESSED is the most quoted word pair in English and the most emotionally accurate."}],"epilogue":"Three groups of things you can hold and one group of things you have to squint at. That ratio is roughly the house style."},
{"id":3,"title":"Board Games Night","diff":1,"groups":[{"name":"CLASSIC BOARD GAMES","colour":"y","tiles":["MONOPOLY","SCRABBLE","CLUEDO","RISK"],"note":"Cluedo outside North America, Clue inside it — same lead pipe, same conservatory."},{"name":"CHESS PIECES","colour":"g","tiles":["PAWN","ROOK","BISHOP","KNIGHT"],"note":"The rook is a castle everywhere except in English chess notation, where it stubbornly stays a bird."},{"name":"CARD GAMES","colour":"b","tiles":["BRIDGE","RUMMY","HEARTS","WHIST"],"note":"Bridge grew out of whist, hearts is a trick-avoidance game, and rummy is the ancestor of half your phone's card apps."},{"name":"___ MATE","colour":"p","tiles":["CHECK","ROOM","SOUL","CLASS"],"note":"Checkmate, roommate, soulmate, classmate — and if you're unlucky, all four at once."}],"epilogue":"CHECK is bait and it is meant to be: it is the only tile that belongs to chess in feeling and to nothing in chess by definition. Count the pieces — there are exactly four without it."},
{"id":4,"title":"Weather Report","diff":2,"groups":[{"name":"PRECIPITATION","colour":"y","tiles":["SLEET","HAIL","DRIZZLE","FLURRY"],"note":"Sleet is the argument between rain and snow; a flurry is snow that isn't committing."},{"name":"CLOUD TYPES","colour":"g","tiles":["CIRRUS","CUMULUS","STRATUS","NIMBUS"],"note":"Luke Howard named them in 1802 in Latin so the whole world could use the same sky."},{"name":"WINDS","colour":"b","tiles":["GALE","ZEPHYR","SQUALL","GUST"],"note":"Zephyrus was the Greek west wind, the mild one. A squall is the opposite temperament."},{"name":"___ STORM","colour":"p","tiles":["BRAIN","SAND","FIRE","THUNDER"],"note":"Brainstorm, sandstorm, firestorm, thunderstorm. Only one of them is scheduled in a calendar."}],"epilogue":"HAIL is the whole puzzle. It is real precipitation and a real storm, and the only way to settle it is to notice that SLEET, DRIZZLE and FLURRY have nowhere else on earth to go."},
{"id":5,"title":"Anatomy Lesson","diff":2,"groups":[{"name":"FLOWERS","colour":"y","tiles":["DAHLIA","PEONY","ASTER","ZINNIA"],"note":"All four are late-summer bloomers, and all four are named after botanists except the aster, which is just Greek for 'star'."},{"name":"BONES","colour":"g","tiles":["FEMUR","TIBIA","ULNA","SCAPULA"],"note":"Thigh, shin, forearm, shoulder blade. The femur is the longest bone you own."},{"name":"PARTS OF THE EYE","colour":"b","tiles":["IRIS","RETINA","CORNEA","PUPIL"],"note":"The pupil is not a thing at all — it is the hole the iris makes."},{"name":"HOMOPHONES OF BODY PARTS","colour":"p","tiles":["MUSSEL","NAVAL","HEAL","LUMBER"],"note":"Muscle, navel, heel, lumbar. Say them out loud and the board rearranges itself."}],"epilogue":"IRIS is a flower. It is also, inconveniently, the only eye part left once RETINA, CORNEA and PUPIL have taken their seats. The flowers already have four; arithmetic beats botany."},
{"id":6,"title":"Screen Time","diff":2,"groups":[{"name":"COMPUTER PERIPHERALS","colour":"y","tiles":["KEYBOARD","MONITOR","MOUSE","PRINTER"],"note":"The four boxes that came with every beige desktop, three of which still work."},{"name":"RODENTS","colour":"g","tiles":["HAMSTER","GERBIL","CAPYBARA","CHINCHILLA"],"note":"The capybara is the largest rodent alive and, by universal agreement, the most relaxed animal on the planet."},{"name":"WEB BROWSERS","colour":"b","tiles":["SAFARI","CHROME","FIREFOX","EDGE"],"note":"Firefox is a red panda, which is not a fox, which is not a rodent either. The naming committee had a night."},{"name":"___ TRACK","colour":"p","tiles":["SOUND","RACE","BACK","SIDE"],"note":"Soundtrack, racetrack, backtrack, sidetrack. The last two are what this board wants you to do."}],"epilogue":"MOUSE is the rodent you were looking for and the rodent you can't have — HAMSTER, GERBIL, CAPYBARA and CHINCHILLA fill the cage without it, and KEYBOARD, MONITOR and PRINTER are three legs of a four-legged desk."},
{"id":7,"title":"Going Places","diff":2,"groups":[{"name":"WAYS TO CROSS WATER","colour":"y","tiles":["FERRY","BRIDGE","TUNNEL","CAUSEWAY"],"note":"A causeway is the cheat: you don't cross the water, you fill it in."},{"name":"AIRPORT FEATURES","colour":"g","tiles":["TERMINAL","CAROUSEL","RUNWAY","CONCOURSE"],"note":"Everything here is a place you stand still, except the one thing that spins."},{"name":"FAIRGROUND ATTRACTIONS","colour":"b","tiles":["WALTZER","DODGEMS","COCONUT SHY","GHOST TRAIN"],"note":"The waltzer spins you, the dodgems dent you, the coconut shy has never in recorded history given up a coconut."},{"name":"___ PORT","colour":"p","tiles":["PASS","CAR","TRANS","SUP"],"note":"Passport, carport, transport, support. Only the first one gets you through the airport."}],"epilogue":"CAROUSEL wants to go to the fairground and the fairground is full. Somebody has to stand at baggage claim."},
{"id":8,"title":"Fully Booked","diff":2,"groups":[{"name":"FINGERS","colour":"y","tiles":["THUMB","RING","PINKY","MIDDLE"],"note":"Anatomists will tell you the thumb is not a finger. Anatomists are not invited to game night."},{"name":"PARTS OF A BOOK","colour":"g","tiles":["SPINE","INDEX","CHAPTER","GLOSSARY"],"note":"The index is the part nobody writes and everybody uses."},{"name":"ONE-WORD SHAKESPEARE PLAYS","colour":"b","tiles":["OTHELLO","MACBETH","CYMBELINE","CORIOLANUS"],"note":"Othello and Macbeth get revived every season; Cymbeline and Coriolanus get revived when a theatre feels brave."},{"name":"___ WORM","colour":"p","tiles":["BOOK","EARTH","SILK","TAPE"],"note":"Bookworm, earthworm, silkworm, tapeworm — in descending order of how much you'd like to be one."}],"epilogue":"Two tiles pull double duty in opposite directions: INDEX is a finger stuck in a book, RING is a finger stuck in a parasite. Follow the ones with no options — SPINE, CHAPTER and GLOSSARY need a fourth, and THUMB, PINKY and MIDDLE need a fourth, and there is exactly one way to feed them both."},
{"id":9,"title":"Music Lesson","diff":2,"groups":[{"name":"WOODWIND INSTRUMENTS","colour":"y","tiles":["OBOE","CLARINET","BASSOON","FLUTE"],"note":"The modern flute is made of metal and is still woodwind, because the family is about how you make the noise, not what out of."},{"name":"ITALIAN MUSICAL DIRECTIONS","colour":"g","tiles":["FORTE","LEGATO","STACCATO","ANDANTE"],"note":"Loud, smooth, detached, walking pace. Andante literally means 'going', which is the most Italian tempo marking possible."},{"name":"TYPES OF SCALE","colour":"b","tiles":["MAJOR","MINOR","CHROMATIC","PENTATONIC"],"note":"The pentatonic scale turns up independently in Chinese, Celtic, West African and blues music — five notes that everybody found on their own."},{"name":"___ NOTE","colour":"p","tiles":["KEY","FOOT","BANK","SIDE"],"note":"Keynote, footnote, banknote, sidenote. Only one of them is ever delivered from a stage."}],"epilogue":"MAJOR and MINOR are keys and scales at once, and KEY is neither — it's a compound word waiting for NOTE. When two tiles could join a group and only one seat is free, take the tile that can't go anywhere else."},
{"id":10,"title":"The Sporting Life","diff":2,"groups":[{"name":"TENNIS SCORING TERMS","colour":"y","tiles":["DEUCE","LOVE","ACE","LET"],"note":"Love for zero probably comes from l'oeuf, the French egg. Deuce from 'à deux', two points to go."},{"name":"IN A DECK OF CARDS","colour":"g","tiles":["JOKER","JACK","CLUBS","SPADES"],"note":"The joker is a 19th-century American invention, added so euchre could have a top trump."},{"name":"GOLF SCORES","colour":"b","tiles":["BIRDIE","EAGLE","BOGEY","ALBATROSS"],"note":"Bogey came first and used to mean par; when standards rose it slid a shot backwards and the birds moved in."},{"name":"___ SHOT","colour":"p","tiles":["LONG","SLAP","BUCK","MUG"],"note":"Longshot, slapshot, buckshot, mugshot. Two sports, one weapon, one bad night."}],"epilogue":"ACE belongs to the cards in every ordinary sense and to tennis in this one; CLUBS belongs to golf in every ordinary sense and to the deck in this one. They swap places in your head and cancel out — the fixed points are DEUCE, LOVE, LET and three birds and a bogey."},
{"id":11,"title":"Full English","diff":3,"groups":[{"name":"ON A FULL ENGLISH PLATE","colour":"y","tiles":["BACON","BLACK PUDDING","BAKED BEANS","HASH BROWN"],"note":"The immovable four, plus egg, sausage, mushrooms, grilled tomato and whatever your café thinks it's doing."},{"name":"BRITISH FOR 'EXCELLENT'","colour":"g","tiles":["CRACKING","SMASHING","BRILLIANT","TOP-NOTCH"],"note":"Three of them describe breaking something. English praise has always had a violent streak."},{"name":"COCKNEY RHYMING SLANG FOR BODY PARTS","colour":"b","tiles":["PLATES OF MEAT","BOAT RACE","MINCE PIES","LOAF OF BREAD"],"note":"Feet, face, eyes, head — and 'use your loaf' is the only one that escaped into general English."},{"name":"___ FAST","colour":"p","tiles":["BREAK","HOLD","STEAD","BEL"],"note":"Breakfast, holdfast, steadfast — and Belfast, which sneaks in on sound alone."}],"epilogue":"Two food groups and one of them isn't food. LOAF OF BREAD is the pivot: put it on the plate and the rhyming slang is a body part short, which is a sentence with an unfortunate double meaning."},
{"id":12,"title":"Elements of Style","diff":3,"groups":[{"name":"NOBLE GASES","colour":"y","tiles":["HELIUM","NEON","ARGON","XENON"],"note":"Argon means 'lazy', xenon means 'stranger', neon means 'new'. Ramsay named most of them and was clearly having fun."},{"name":"SUPERMAN LORE","colour":"g","tiles":["KRYPTONITE","METROPOLIS","LOIS LANE","DAILY PLANET"],"note":"Krypton the planet is named after krypton the noble gas, discovered in 1898 and meaning 'hidden'."},{"name":"ELEMENTS NAMED AFTER PLACES","colour":"b","tiles":["POLONIUM","FRANCIUM","GERMANIUM","AMERICIUM"],"note":"Marie Curie named polonium for a Poland that did not exist on any map in 1898. It was a political act with a chemistry paper attached."},{"name":"___ SIGN","colour":"p","tiles":["PLUS","PEACE","STOP","DOLLAR"],"note":"Plus sign, peace sign, stop sign, dollar sign — a maths symbol, a hand shape, an octagon and a currency."}],"epilogue":"The noble gases and the place-name elements are both periodic-table groups, which is the misdirection — but no noble gas here is named for a place, and nothing in the other four is a gas. NEON is the only tile with a foot in two worlds."},
{"id":13,"title":"Star Turn","diff":3,"groups":[{"name":"ZODIAC SIGNS","colour":"y","tiles":["LIBRA","VIRGO","ARIES","GEMINI"],"note":"Libra is the only zodiac sign that isn't an animal or a person — it's a set of scales."},{"name":"CONSTELLATIONS OUTSIDE THE ZODIAC","colour":"g","tiles":["ORION","CASSIOPEIA","URSA MAJOR","LYRA"],"note":"Cassiopeia was chained to her throne upside down as a punishment for vanity, which is the most Greek sentence available."},{"name":"GALILEAN MOONS OF JUPITER","colour":"b","tiles":["IO","EUROPA","GANYMEDE","CALLISTO"],"note":"Galileo spotted all four in January 1610 and proved not everything orbits us. Ganymede is bigger than Mercury."},{"name":"___ STRUCK","colour":"p","tiles":["STAR","THUNDER","MOON","AWE"],"note":"Starstruck, thunderstruck, moonstruck, awestruck. Every one of them is a way of saying you stopped thinking."}],"epilogue":"Every zodiac sign is also a constellation, which is why the second group had to say 'outside the zodiac' out loud. The only genuinely loose tile is MOON, and IO, EUROPA, GANYMEDE and CALLISTO were never going to make room."},
{"id":14,"title":"Green Room","diff":3,"groups":[{"name":"SHADES OF GREEN","colour":"y","tiles":["OLIVE","EMERALD","JADE","SAGE"],"note":"Three of them are named after a stone, a fruit and a herb. Colour naming has never had an original idea."},{"name":"HERBS","colour":"g","tiles":["BASIL","THYME","OREGANO","TARRAGON"],"note":"Oregano and marjoram are the same genus; tarragon is a relative of wormwood, which explains a lot about tarragon."},{"name":"GEMSTONES","colour":"b","tiles":["GARNET","TOPAZ","OPAL","AMETHYST"],"note":"Amethyst means 'not drunk' — the Greeks believed the stone would keep you sober. It does not."},{"name":"___ HOUSE","colour":"p","tiles":["GREEN","LIGHT","FARM","WARE"],"note":"Greenhouse, lighthouse, farmhouse, warehouse. One grows things, one saves lives, two store things."}],"epilogue":"Four separate tiles want to defect and none of them can, because BASIL, THYME, OREGANO, GARNET, TOPAZ, OPAL and AMETHYST have no second passport at all. Fill the groups that have no choices first and the colours are whatever survives."},
{"id":15,"title":"Small Talk","diff":3,"groups":[{"name":"WORDS MEANING TINY","colour":"y","tiles":["PETITE","SLIGHT","WEE","MINUTE"],"note":"MY-newt, not MIN-it. Same spelling, different word, different Latin root — and the whole reason this board exists."},{"name":"UNITS OF TIME","colour":"g","tiles":["SECOND","FORTNIGHT","DECADE","MILLENNIUM"],"note":"Fortnight is 'fourteen nights' worn down by seven centuries of use, and Americans have never adopted it."},{"name":"A BRIEF MOMENT, INFORMALLY","colour":"b","tiles":["JIFFY","TICK","FLASH","HEARTBEAT"],"note":"A jiffy is genuinely a unit in physics and electronics — anywhere from a millisecond to the time light takes to cross a fermi."},{"name":"___ GLASS","colour":"p","tiles":["HOUR","SPY","PLEXI","LOOKING"],"note":"Hourglass, spyglass, plexiglass, looking glass. Two for seeing far, one for seeing yourself, one for seeing time run out."}],"epilogue":"MINUTE and HOUR both look like clock parts and neither one is. Notice that SECOND, FORTNIGHT, DECADE and MILLENNIUM already make four, and the rest of the board unlocks in about a second."},
{"id":16,"title":"Say That Again","diff":3,"groups":[{"name":"PALINDROMES","colour":"y","tiles":["CIVIC","RADAR","MADAM","KAYAK"],"note":"Radar is an acronym that happens to read the same both ways, which its inventors did not plan and have never stopped being asked about."},{"name":"NO VOWEL LETTERS","colour":"g","tiles":["RHYTHM","CRYPT","LYNX","GYPSY"],"note":"Y is doing all the work in three of these and none of it in the fourth."},{"name":"CONTAIN ALL FIVE VOWELS","colour":"b","tiles":["SEQUOIA","FACETIOUS","EDUCATION","DIALOGUE"],"note":"FACETIOUS has them in order, A-E-I-O-U, which is the only reason anybody remembers the word."},{"name":"THEIR OWN OPPOSITE","colour":"p","tiles":["CLEAVE","SANCTION","DUST","OVERSIGHT"],"note":"Cleave together or apart, sanction it or ban it, dust a cake or a shelf, oversight as care or as failure. Contronyms — English arguing with itself."}],"epilogue":"A rare board with no double agents: every tile qualifies for exactly one group and the difficulty is entirely in noticing what the groups are. If the purple took you a while, that's the intended shape — the connection is a property of the word, not of the thing."},
{"id":17,"title":"Menu Reading","diff":3,"groups":[{"name":"WAYS TO SERVE EGGS","colour":"y","tiles":["POACHED","SCRAMBLED","CODDLED","OVER EASY"],"note":"Coddled means barely set in a lidded pot in gentle water — the technique that gave us the verb for spoiling someone."},{"name":"FRENCH MOTHER SAUCES","colour":"g","tiles":["BÉCHAMEL","VELOUTÉ","ESPAGNOLE","HOLLANDAISE"],"note":"Carême named four; Escoffier added tomate and made it five. Every classical French sauce is a child of one of them."},{"name":"PROTECTED-ORIGIN CHEESES","colour":"b","tiles":["ROQUEFORT","MANCHEGO","STILTON","GRUYÈRE"],"note":"Stilton's protection is famously strict — it cannot legally be made in the village of Stilton, which is in the wrong county."},{"name":"___ WHITE","colour":"p","tiles":["EGG","SNOW","OFF","BONE"],"note":"Egg white, snow white, off-white, bone white. Two are colours on a paint chart, one is a fairy tale, one is breakfast."}],"epilogue":"The egg group is about methods, not ingredients — POACHED, SCRAMBLED, CODDLED and OVER EASY are all things you do, and EGG is a thing you have. Hollandaise, incidentally, is made of egg and belongs to France instead."},
{"id":18,"title":"Island Life","diff":3,"groups":[{"name":"ISLAND COUNTRIES","colour":"y","tiles":["CYPRUS","ICELAND","FIJI","JAMAICA"],"note":"Fiji is about 330 islands; Iceland is essentially one; Cyprus is one island and, unhappily, two administrations."},{"name":"GREEK ISLANDS","colour":"g","tiles":["CRETE","RHODES","NAXOS","SANTORINI"],"note":"Santorini is the rim of a volcano that blew its own middle out around 1600 BC and possibly took Minoan Crete with it."},{"name":"FICTIONAL ISLANDS","colour":"b","tiles":["LILLIPUT","ATLANTIS","NEVERLAND","AMITY"],"note":"Amity is the beach town in Jaws, whose mayor kept it open. Atlantis is Plato's, invented for an argument about hubris."},{"name":"ADD 'LAND' FOR A COUNTRY","colour":"p","tiles":["FIN","IRE","POL","THAI"],"note":"Finland, Ireland, Poland, Thailand. ICE would have worked too, which is exactly why it's already spoken for."}],"epilogue":"ICELAND is the joke: it is a genuine island country and it is also, letter for letter, ICE plus LAND. It sits in the group that needs it, and the purple has to make do with FIN, IRE, POL and THAI."},
{"id":19,"title":"Money Talks","diff":3,"groups":[{"name":"CURRENCIES","colour":"y","tiles":["PESO","DINAR","RUPEE","KRONA"],"note":"Dinar comes from the Roman denarius and rupee from Sanskrit rupya, 'wrought silver'. Money words travel further than money."},{"name":"SLANG FOR MONEY","colour":"g","tiles":["DOUGH","BREAD","QUID","LOOT"],"note":"Dough and bread say the same thing twice: money is what you eat with."},{"name":"SQUARES ON A UK MONOPOLY BOARD","colour":"b","tiles":["MAYFAIR","OLD KENT ROAD","FREE PARKING","WATER WORKS"],"note":"Mayfair costs £400 and Old Kent Road £60, a ratio London property has spent a century trying to beat."},{"name":"___ BANK","colour":"p","tiles":["BLOOD","RIVER","PIGGY","DATA"],"note":"Blood bank, river bank, piggy bank, data bank. Only one of them holds money, and it's the pig."}],"epilogue":"QUID is the honest ambiguity here — it names a real currency the way 'buck' names the dollar. PESO, DINAR, RUPEE and KRONA are the four that appear on actual banknotes, and slang gets what's left."},
{"id":20,"title":"Get a Grip","diff":3,"groups":[{"name":"KNOTS","colour":"y","tiles":["REEF","BOWLINE","CLOVE HITCH","SHEEPSHANK"],"note":"The bowline is the one you can untie after it's been loaded; the reef knot is the one everybody ties and half of them tie as a granny."},{"name":"MARTIAL ARTS","colour":"g","tiles":["JUDO","AIKIDO","KARATE","CAPOEIRA"],"note":"Capoeira was developed by enslaved Africans in Brazil and disguised as dance, which is why it is fought to music."},{"name":"YOGA POSES","colour":"b","tiles":["COBRA","WARRIOR","CHILD'S POSE","DOWNWARD DOG"],"note":"Downward dog is adho mukha svanasana; the warrior is virabhadrasana, named for a rather angry avatar of Shiva."},{"name":"___ HOLD","colour":"p","tiles":["HOUSE","STRONG","FREE","THRESH"],"note":"Household, stronghold, freehold, threshold. Three kinds of property and one doorway."}],"epilogue":"Every group here is about grip, stance or holding on, so the categories blur by design. WARRIOR is the tile that reads as combat and isn't — JUDO, AIKIDO, KARATE and CAPOEIRA are the four that actually hit back."},
{"id":21,"title":"Table for Two","diff":3,"groups":[{"name":"COFFEE ORDERS","colour":"y","tiles":["LATTE","CORTADO","MACCHIATO","FLAT WHITE"],"note":"A cortado is equal parts espresso and warm milk; a macchiato is espresso 'stained' with a spoonful. The flat white is an antipodean argument that never ended."},{"name":"TEAS AND INFUSIONS","colour":"g","tiles":["OOLONG","ROOIBOS","MATCHA","DARJEELING"],"note":"Rooibos is not tea at all — it's a South African bush — and matcha is the whole leaf ground up rather than steeped and thrown away."},{"name":"COCKTAILS NAMED AFTER PLACES","colour":"b","tiles":["MANHATTAN","MOSCOW MULE","LONG ISLAND","BRONX"],"note":"The Bronx is a 1900s gin, vermouth and orange juice cocktail that was once as famous as the Martini and is now ordered by nobody."},{"name":"___ PRESS","colour":"p","tiles":["FRENCH","BENCH","CIDER","PRINTING"],"note":"French press, bench press, cider press, printing press. All four squeeze something out of something else."}],"epilogue":"FRENCH is the only tile with a foot in the café. LATTE, CORTADO, MACCHIATO and FLAT WHITE are drinks you order by name, and a French press is a piece of equipment — which is the distinction the board is testing."},
{"id":22,"title":"Loose Change","diff":3,"groups":[{"name":"US COINS","colour":"y","tiles":["PENNY","NICKEL","DIME","QUARTER"],"note":"The dime is the smallest US coin by size and the only one that doesn't say what it's worth anywhere on it."},{"name":"METALS","colour":"g","tiles":["TITANIUM","TIN","ZINC","LEAD"],"note":"Titanium is as strong as steel and 45% lighter; lead is soft enough to scratch with a fingernail."},{"name":"BRITISH SLANG FOR PRISON","colour":"b","tiles":["CLINK","NICK","SLAMMER","POKEY"],"note":"The Clink was a real gaol in Southwark from the 12th century until a mob burned it down in 1780. The name outlived the building by 250 years."},{"name":"___ MINE","colour":"p","tiles":["GOLD","LAND","COAL","DIAMOND"],"note":"Gold mine, landmine, coal mine, diamond mine. Only one of them you'd rather not find."}],"epilogue":"NICKEL is a metal that got a coin named after it, and NICK is a prison that sounds like the metal. TITANIUM, TIN, ZINC and LEAD have never been legal tender in America, so the metal shelf fills without it."},
{"id":23,"title":"Strike Anywhere","diff":4,"groups":[{"name":"THINGS YOU STRIKE","colour":"y","tiles":["MATCH","DEAL","POSE","BALANCE"],"note":"You strike a match, a deal, a pose and a balance — four completely unrelated verbs wearing the same coat."},{"name":"OLYMPIC ATHLETICS EVENTS","colour":"g","tiles":["HURDLES","JAVELIN","SHOT PUT","STEEPLECHASE"],"note":"The steeplechase has a water jump because it descends from a horse race across country between two church steeples."},{"name":"PARTS OF A DRUM KIT","colour":"b","tiles":["SNARE","HI-HAT","CYMBAL","TOM"],"note":"The snare is named for the wires stretched under the bottom head; without them it's just a very disappointed tom."},{"name":"___ STICK","colour":"p","tiles":["CHAP","YARD","DRUM","LIP"],"note":"Chapstick, yardstick, drumstick, lipstick. Two of them go on your face."}],"epilogue":"Two tiles argue about the same kit: DRUM wants to join the drums and CYMBAL wants to join the things you strike, and they cancel out. SNARE, HI-HAT and TOM cannot be anything else, and MATCH, DEAL and POSE cannot be anything else, so the leftovers sort themselves."},
{"id":24,"title":"Alphabet Soup","diff":4,"groups":[{"name":"GREEK LETTERS","colour":"y","tiles":["SIGMA","DELTA","OMEGA","LAMBDA"],"note":"Sigma became the summation sign, delta the symbol for change, lambda the wavelength, and omega the end of everything."},{"name":"NATO ALPHABET WORDS","colour":"g","tiles":["TANGO","FOXTROT","WHISKEY","ROMEO"],"note":"The 1956 alphabet was tested across accents and radio static; the words were chosen because they survive being half-heard, not because they're pretty."},{"name":"BALLROOM DANCES","colour":"b","tiles":["WALTZ","QUICKSTEP","RUMBA","SAMBA"],"note":"The quickstep came out of the 1920s when bands played the foxtrot too fast and the dancers simply kept up."},{"name":"___ FORCE","colour":"p","tiles":["AIR","TASK","BRUTE","WORK"],"note":"Air force, task force, brute force, workforce. Only one of them is a solution to a maths problem."}],"epilogue":"Two of the NATO words are dances and one of the Greek letters is a NATO word, so three tiles are pulling sideways at once. The anchor is that SIGMA, OMEGA and LAMBDA are Greek and nothing else — DELTA has to stay to make four, and once it does, TANGO and FOXTROT have to stay too."},
{"id":25,"title":"Silent Treatment","diff":4,"groups":[{"name":"SILENT B","colour":"y","tiles":["DEBT","SUBTLE","PLUMBER","DOUBT"],"note":"Debt and doubt never had a B in English — 16th-century scholars inserted them to show off the Latin, and we've been silently paying for it since."},{"name":"SILENT K","colour":"g","tiles":["KNEEL","KNUCKLE","KNACK","KNOLL"],"note":"The K was pronounced until about 1600. Chaucer's knight was a k-nicht."},{"name":"SILENT P","colour":"b","tiles":["PSALM","PNEUMONIA","RECEIPT","CORPS"],"note":"Greek gave us the ps- and pn- pairs and English refused to say either. Corps is French and drops the P and the S together."},{"name":"SILENT L","colour":"p","tiles":["SALMON","CALM","YOLK","WOULD"],"note":"Salmon had no L at all until Latin-minded spellers put one in, and nobody has ever pronounced it."}],"epilogue":"PSALM is the double agent and the resolution is arithmetic, not phonetics: SALMON, CALM, YOLK and WOULD already make four silent Ls, and PNEUMONIA, RECEIPT and CORPS need a fourth silent P. There is only one word that can do the job."},
{"id":26,"title":"Two of a Kind","diff":4,"groups":[{"name":"THINGS THAT COME IN PAIRS","colour":"y","tiles":["SCISSORS","TROUSERS","BINOCULARS","TWEEZERS"],"note":"All four are grammatically plural and physically singular, which is why you buy 'a pair' of each."},{"name":"___ SOME","colour":"g","tiles":["HAND","AWE","TIRE","LONE"],"note":"Handsome, awesome, tiresome, lonesome. 'Handsome' originally meant easy to handle."},{"name":"COLLECTIVE NOUNS FOR BIRDS","colour":"b","tiles":["MURDER","PARLIAMENT","CHARM","MURMURATION"],"note":"A murder of crows, a parliament of owls, a charm of finches, a murmuration of starlings. Most were invented in a 15th-century hunting manual by people showing off."},{"name":"QUARK FLAVOURS","colour":"p","tiles":["UP","DOWN","STRANGE","BOTTOM"],"note":"Six flavours: up, down, strange, charm, top and bottom. Gell-Mann took 'quark' from a line in Finnegans Wake and the naming has been unserious ever since."}],"epilogue":"CHARM is a quark and a flock, and both readings are completely legitimate — which is why UP, DOWN, STRANGE and BOTTOM had to be four on their own. MURDER, PARLIAMENT and MURMURATION have no subatomic ambitions."},
{"id":27,"title":"Shades of Meaning","diff":4,"groups":[{"name":"WORDS MEANING FAKE","colour":"y","tiles":["BOGUS","PHONY","SHAM","ERSATZ"],"note":"Ersatz is German for 'replacement' and entered English through wartime coffee made of acorns."},{"name":"WORDS MEANING STUBBORN","colour":"g","tiles":["DOGGED","MULISH","OBSTINATE","PIGHEADED"],"note":"Three of these blame an animal for a human failing, which is the most human thing about them."},{"name":"ADJECTIVES FROM ANIMALS","colour":"b","tiles":["BOVINE","FELINE","ASININE","VULPINE"],"note":"Cow, cat, ass, fox. Only asinine has drifted so far from the donkey that people forget it was ever about one."},{"name":"___ FACED","colour":"p","tiles":["TWO","BARE","POKER","STONE"],"note":"Two-faced, barefaced, poker-faced, stone-faced. Three are expressions and one is a character judgement."}],"epilogue":"Three tiles in the stubborn group are literally adjectives made from animals, which looks like a fatal ambiguity and isn't: BOVINE, FELINE, ASININE and VULPINE are already four, and none of them means stubborn. The animal group is full before the argument starts."},
{"id":28,"title":"Take Your Pick","diff":4,"groups":[{"name":"PARTS OF A GUITAR","colour":"y","tiles":["FRET","NUT","TUNING PEG","SOUNDHOLE"],"note":"The nut is the slotted strip at the top of the neck that sets the string spacing and the open-string height. Get it wrong and nothing else can be right."},{"name":"NUTS","colour":"g","tiles":["CASHEW","PECAN","MACADAMIA","WALNUT"],"note":"Botanically almost none of these is a nut — the cashew is a seed hanging off a fruit, the pecan and walnut are drupes."},{"name":"SCREWDRIVER HEADS","colour":"b","tiles":["PHILLIPS","FLATHEAD","TORX","HEX"],"note":"Phillips was designed to cam out on purpose so an assembly-line driver couldn't overtighten. Every stripped screw since is a feature."},{"name":"___ PICK","colour":"p","tiles":["ICE","TOOTH","NIT","HAND"],"note":"Ice pick, toothpick, nitpick, handpick. Two are objects, two are habits."}],"epilogue":"NUT is the whole board. CASHEW, PECAN, MACADAMIA and WALNUT are four already, and FRET, TUNING PEG and SOUNDHOLE are three looking for a fourth — which is exactly the sort of counting that makes a purple collapse."},
{"id":29,"title":"Long Story Short","diff":4,"groups":[{"name":"ACRONYMS THAT BECAME ORDINARY WORDS","colour":"y","tiles":["LASER","SCUBA","TASER","SONAR"],"note":"Light Amplification by Stimulated Emission of Radiation; Self-Contained Underwater Breathing Apparatus; Sound Navigation and Ranging. Nobody has expanded any of them out loud since 1975."},{"name":"PORTMANTEAU WORDS","colour":"g","tiles":["BRUNCH","SMOG","MOTEL","PODCAST"],"note":"Smog is smoke plus fog and was coined in 1905 about London. Podcast is iPod plus broadcast, which now outlives the iPod."},{"name":"WORDS FROM A PERSON'S NAME","colour":"b","tiles":["SANDWICH","BOYCOTT","CARDIGAN","SILHOUETTE"],"note":"The Earl of Sandwich, Captain Boycott who was frozen out by his tenants, the Earl of Cardigan of Light Brigade fame, and Étienne de Silhouette, a finance minister so stingy his name meant 'done on the cheap'."},{"name":"THEIR OWN PLURAL","colour":"p","tiles":["SHEEP","DEER","SERIES","AIRCRAFT"],"note":"One sheep, two sheep. English gave up on these and never came back."}],"epilogue":"TASER is genuinely both: an acronym and a word from somebody's name, because the acronym IS somebody's name. SANDWICH, BOYCOTT, CARDIGAN and SILHOUETTE are already four earls and a civil servant, so the acronyms keep their stun gun."},
{"id":30,"title":"Hidden Depths","diff":4,"groups":[{"name":"SEAS","colour":"y","tiles":["CORAL","BALTIC","ARAL","TASMAN"],"note":"The Aral is the cautionary one — it was the fourth-largest lake on earth in 1960 and is now mostly desert with rusting trawlers in it."},{"name":"SHADES OF RED","colour":"g","tiles":["CRIMSON","SCARLET","VERMILION","CARMINE"],"note":"Carmine and crimson both come from the kermes insect, crushed for dye since antiquity. Vermilion is ground cinnabar, which is mercury ore, which is why old painters died young."},{"name":"MUSIC GENRES","colour":"b","tiles":["SKA","GRIME","DRILL","GARAGE"],"note":"Ska came first in Jamaica, garage out of New York and then very differently out of London, and grime and drill out of that. Four genres, one family tree."},{"name":"___ BAND","colour":"p","tiles":["ARM","HEAD","WAIST","BROAD"],"note":"Armband, headband, waistband, broadband. Three of them hold something up."}],"epilogue":"CORAL is a colour that got a sea named after it, which is the reverse of how these usually go. CRIMSON, SCARLET, VERMILION and CARMINE are four reds already, and BALTIC, ARAL and TASMAN are three seas short of a set."},
{"id":31,"title":"Change of Address","diff":5,"groups":[{"name":"GREETINGS AROUND THE WORLD","colour":"y","tiles":["ALOHA","CIAO","SALAAM","NAMASTE"],"note":"Aloha and ciao both mean hello AND goodbye; salaam and namaste are both blessings that got shortened into doorway small talk."},{"name":"EUROPEAN CAPITALS","colour":"g","tiles":["LISBON","TALLINN","ZAGREB","VILNIUS"],"note":"Lisbon is older than Rome; Tallinn's old town survived the twentieth century almost intact, which almost nothing in the Baltics did."},{"name":"FOUR-LETTER COUNTRIES","colour":"b","tiles":["CHAD","PERU","IRAN","LAOS"],"note":"There are seven or eight depending on how you count Cuba, Fiji, Mali and Togo. These four are the ones that fit."},{"name":"ANAGRAMS OF EUROPEAN CAPITALS","colour":"p","tiles":["MORE","SOLO","PAIRS","HASTEN"],"note":"Rome, Oslo, Paris, Athens. Four ordinary English words hiding four capitals, none of which are the four capitals in the second group."}],"epilogue":"LAOS and SOLO are anagrams of the same capital, which is the trick: only one of them can sit in the purple, and LAOS has a day job. CHAD, PERU and IRAN aren't anagrams of anything European, so the countries need their fourth."},
{"id":32,"title":"Elementary","diff":4,"groups":[{"name":"SHERLOCK HOLMES THINGS","colour":"y","tiles":["BAKER STREET","DEERSTALKER","MORIARTY","WATSON"],"note":"Conan Doyle never wrote 'elementary, my dear Watson' and never described a deerstalker — the hat was Sidney Paget's idea in The Strand."},{"name":"FICTIONAL DETECTIVES","colour":"g","tiles":["POIROT","MARPLE","MAIGRET","WIMSEY"],"note":"Christie got so tired of Poirot she called him a detestable little creature in her diary and kept writing him for another forty years."},{"name":"FAMOUS COMPUTERS","colour":"b","tiles":["DEEP BLUE","HAL","ALPHAGO","ENIAC"],"note":"ENIAC in 1945 filled a room and weighed 27 tonnes; Deep Blue beat Kasparov in 1997; AlphaGo beat Lee Sedol in 2016 with a move no human would have played."},{"name":"___ HOUND","colour":"p","tiles":["GREY","NEWS","FOX","WOLF"],"note":"Greyhound, newshound, foxhound, wolfhound. The Baskerville one is not on the list and you should be grateful."}],"epilogue":"WATSON is a doctor and a computer, and both are famous enough to earn a seat. DEEP BLUE, HAL, ALPHAGO and ENIAC are already four machines, so the doctor goes back to Baker Street — which is where the deerstalker, incidentally, never actually was."},
{"id":33,"title":"Kitchen Chemistry","diff":4,"groups":[{"name":"THINGS THAT RISE","colour":"y","tiles":["SOUFFLÉ","TIDE","SUN","CURTAIN"],"note":"A soufflé rises because trapped water turns to steam, not because of anything magical. The curtain rises because someone pulls a rope."},{"name":"LEAVENING AGENTS","colour":"g","tiles":["YEAST","BAKING SODA","BAKING POWDER","EGG WHITE"],"note":"Yeast is alive, baking soda needs an acid to react with, baking powder brings its own acid, and egg white just traps air and holds on."},{"name":"___ PROOF","colour":"b","tiles":["FOOL","WATER","BULLET","FIRE"],"note":"Foolproof, waterproof, bulletproof, fireproof. In a bakery, 'proof' means letting the dough rise, which is a different word entirely."},{"name":"FRENCH COOKING TECHNIQUES","colour":"p","tiles":["SAUTÉ","BLANCH","FLAMBÉ","JULIENNE"],"note":"Sauté means 'jumped', blanchir means 'to whiten', flamber means 'to flame'. Julienne is somebody's name and nobody is sure whose."}],"epilogue":"The joke is buried in the purple: to 'proof' dough is to let it rise, so the ___ PROOF group is thematically perfect and grammatically irrelevant. YEAST makes things rise rather than rising itself, and SOUFFLÉ, TIDE, SUN and CURTAIN do the rising in person."},
{"id":34,"title":"Sound Alike","diff":5,"groups":[{"name":"HOMOPHONES OF NUMBERS","colour":"y","tiles":["WON","TOO","FOR","ATE"],"note":"One, two, four, eight. English numbers collide with English grammar words more than any other language has the decency to allow."},{"name":"HOMOPHONES OF ANIMALS","colour":"g","tiles":["BARE","DEAR","HAIR","YEW"],"note":"Bear, deer, hare, ewe. Three of them are things you'd find in an English wood and one is a churchyard tree that sounds like a sheep."},{"name":"HOMOPHONES OF WEATHER","colour":"b","tiles":["REIGN","HALE","SON","DUE"],"note":"Rain, hail, sun, dew. 'Hale' as in hale and hearty — from the same root as 'whole', nothing to do with the ice."},{"name":"HOMOPHONES OF MUSICAL NOTES","colour":"p","tiles":["DOUGH","RAY","ME","TEA"],"note":"Do, re, mi, ti. The solfège syllables come from the first lines of a Latin hymn to John the Baptist, which is a long way to go for a scale."}],"epilogue":"Every tile is a homophone of something, so the categories are four different somethings — and the trap is that RAY is genuinely a fish, not merely a word that sounds like one. BARE, DEAR, HAIR and YEW are all one letter away from a mammal, and none of them is an animal itself."},
{"id":35,"title":"State of Play","diff":5,"groups":[{"name":"US STATE CAPITALS","colour":"y","tiles":["ALBANY","PIERRE","SALEM","AUSTIN"],"note":"Pierre, South Dakota has about 14,000 people and is the second-smallest state capital in the country."},{"name":"SHAKESPEARE'S ITALIAN SETTINGS","colour":"g","tiles":["VERONA","VENICE","PADUA","MESSINA"],"note":"Verona for Romeo and Juliet, Venice for the Merchant and Othello, Padua for the Shrew, Messina for Much Ado. He never went to any of them."},{"name":"___ CITY","colour":"b","tiles":["KANSAS","CARSON","ATLANTIC","SIOUX"],"note":"Kansas City is mostly in Missouri, Atlantic City is on an island, and Sioux City and Sioux Falls are in different states."},{"name":"___ ROCK","colour":"p","tiles":["PUNK","PLYMOUTH","BED","SHAM"],"note":"Punk rock, Plymouth Rock, bedrock, shamrock. Only one of them is a plant and it isn't even a rock."}],"epilogue":"CARSON is a state capital wearing a compound word's clothes, and the only reason it can't be one here is that ALBANY, PIERRE, SALEM and AUSTIN already are four. KANSAS, ATLANTIC and SIOUX need a fourth city and Carson is the only one going."},
{"id":36,"title":"Well Suited","diff":4,"groups":[{"name":"PARTS OF A SUIT JACKET","colour":"y","tiles":["LAPEL","CUFF","VENT","LINING"],"note":"The vent is the slit at the back: none is Italian, one is American, two is English. Tailors will fight you about this."},{"name":"TYPES OF COLLAR","colour":"g","tiles":["MANDARIN","PETER PAN","BUTTON-DOWN","SHAWL"],"note":"The button-down was invented for polo players so the collar wouldn't flap in their faces at a gallop."},{"name":"SUITS IN A TAROT DECK","colour":"b","tiles":["WANDS","CUPS","SWORDS","PENTACLES"],"note":"Wands, cups, swords and pentacles map onto clubs, hearts, spades and diamonds — the tarot came first and the playing deck simplified it."},{"name":"___ LINK","colour":"p","tiles":["MISSING","WEAK","SAUSAGE","CHAIN"],"note":"Missing link, weak link, sausage link, chain link. Two are metaphors, one is a fence, one is breakfast."}],"epilogue":"Two different meanings of 'suit' share a board, which is the misdirection, and CUFF is the tile that actually moves. MISSING, WEAK, SAUSAGE and CHAIN are four links already, so the cuff stays sewn to the sleeve."},
{"id":37,"title":"No Rhyme","diff":4,"groups":[{"name":"WORDS WITH NO PERFECT RHYME","colour":"y","tiles":["ORANGE","SILVER","PURPLE","MONTH"],"note":"There is a hill in Wales called Blorenge and a Scrabble-legal word 'chilver', which is how determined people get about this."},{"name":"KINDS OF PUZZLE","colour":"g","tiles":["SUDOKU","ANAGRAM","REBUS","ACROSTIC"],"note":"Sudoku is Japanese for 'the digits are limited to one occurrence', which is less catchy and more accurate."},{"name":"SPELLED ONLY WITH ROMAN NUMERALS","colour":"b","tiles":["MIX","DIM","MILD","CIVIL"],"note":"Every letter is I, V, X, L, C, D or M. MIX is genuinely 1009 and DIM is genuinely 1499, which is a coincidence English did not plan."},{"name":"COUNTRIES HIDING INSIDE","colour":"p","tiles":["PIRANHA","INCUBATE","NORMALITY","ROMANCE"],"note":"p-IRAN-ha, in-CUBA-te, nor-MALI-ty, r-OMAN-ce. Four countries in four words that have nothing to do with them."}],"epilogue":"No double agents — this board is hard because two of the four categories are properties of the spelling rather than the meaning, and your brain keeps trying to sort by topic. MIX and DIM look like they belong with the puzzles until you notice what letters they are made of."},
{"id":38,"title":"Crossed Wires","diff":5,"groups":[{"name":"TYPES OF CURRENT","colour":"y","tiles":["ALTERNATING","DIRECT","RIP","EDDY"],"note":"Two are electrical and two are water. Eddy currents are actually both — loops of electricity induced in metal, named after the whirl in a river."},{"name":"PARTS OF A CIRCUIT","colour":"g","tiles":["RESISTOR","CAPACITOR","DIODE","FUSE"],"note":"A fuse is a component designed to destroy itself, which is a rare and honourable job description."},{"name":"THINGS YOU BLOW","colour":"b","tiles":["WHISTLE","KISS","BUBBLE","GASKET"],"note":"Blow a whistle, a kiss, a bubble, a gasket. Only one of them costs money to fix."},{"name":"___ WIRE","colour":"p","tiles":["HAY","HIGH","LIVE","TRIP"],"note":"Haywire, high wire, live wire, tripwire. 'Haywire' comes from farm equipment repaired with baling wire until it stopped working entirely."}],"epilogue":"Three tiles are pulling toward the mains and none of them can go: RESISTOR, CAPACITOR and DIODE need a fourth component, and WHISTLE, KISS and BUBBLE need a fourth thing to blow, and there is exactly one tile that can satisfy either. Blow a gasket, blow a fuse — only one of those is a component."},
{"id":39,"title":"Full Circle","diff":5,"groups":[{"name":"PARTS OF A CIRCLE","colour":"y","tiles":["RADIUS","CHORD","ARC","TANGENT"],"note":"A chord joins two points on the circle, an arc is the bit between them, a tangent touches at exactly one point and then leaves forever."},{"name":"MUSIC THEORY TERMS","colour":"g","tiles":["TRIAD","CADENCE","OCTAVE","INTERVAL"],"note":"A triad is three notes stacked in thirds, a cadence is how a phrase lands, an octave is the interval so consonant we gave both notes the same name."},{"name":"TRIGONOMETRIC FUNCTIONS","colour":"b","tiles":["SINE","COSINE","COSECANT","COTANGENT"],"note":"'Sine' is a mistranslation: Sanskrit jya became Arabic jiba, was misread as jaib meaning 'bay', and was rendered into Latin as sinus. The word means 'fold' by accident."},{"name":"___ POINT","colour":"p","tiles":["TURNING","BOILING","PIN","VIEW"],"note":"Turning point, boiling point, pinpoint, viewpoint. Only one of them has a temperature."}],"epilogue":"CHORD and TANGENT both have a completely legitimate second home, and both are trapped by counting: TRIAD, CADENCE, OCTAVE and INTERVAL are already four, and SINE, COSINE, COSECANT and COTANGENT are already four. RADIUS and ARC would be a very lonely group of two."},
{"id":40,"title":"The Last Word","diff":5,"groups":[{"name":"SYNONYMS FOR 'END'","colour":"y","tiles":["FINALE","CONCLUSION","TERMINUS","CLOSE"],"note":"Four different registers of the same idea: theatrical, logical, geographical and plain."},{"name":"AT A RAILWAY STATION","colour":"g","tiles":["PLATFORM","SIGNAL BOX","BUFFERS","SLEEPER"],"note":"The buffers are the shock absorbers at the end of the line, which is why 'hit the buffers' means what it means."},{"name":"PARTS OF A PLAY","colour":"b","tiles":["ACT","SCENE","PROLOGUE","EPILOGUE"],"note":"The prologue tells you what you're about to see and the epilogue tells you what it meant. Everything worth watching is in between."},{"name":"___ CURTAIN","colour":"p","tiles":["IRON","SHOWER","LACE","FINAL"],"note":"Iron curtain, shower curtain, lace curtain, final curtain. The iron one in a theatre is a real fire barrier, which is where Churchill got the phrase."}],"epilogue":"The last board in the archive and it is entirely about endings, which felt like the right note. TERMINUS is the tile that could go either way, and PLATFORM, SIGNAL BOX, BUFFERS and SLEEPER settle it by being four already. Final curtain."}
]},
{"id":"persia","name":"PERSIAN BLUE","blurb":"Nowruz, poets, food, carpets, and the words English quietly borrowed.","boards":[
{"id":1,"title":"Haft-Sin","diff":1,"groups":[{"name":"THE SEVEN S's OF THE HAFT-SIN","colour":"y","tiles":["SABZEH","SAMANU","SENJED","SERKEH"],"note":"Sprouted wheat, wheat pudding, oleaster berries, vinegar — plus seeb (apple), seer (garlic) and somaq to make seven, all beginning with the letter sin."},{"name":"NOWRUZ CUSTOMS","colour":"g","tiles":["SIZDAH BEDAR","FIRE JUMPING","KHANE TAKANI","EIDI"],"note":"Thirteenth-day picnic, the last-Wednesday bonfires of Chaharshanbe Suri, the deep spring clean, and the crisp new banknotes the elders hand out."},{"name":"MONTHS OF THE PERSIAN CALENDAR","colour":"b","tiles":["FARVARDIN","ORDIBEHESHT","KHORDAD","ESFAND"],"note":"The year starts at the spring equinox with Farvardin and ends with Esfand. Iran's calendar is solar and, in astronomical terms, more accurate than the Gregorian one."},{"name":"ALSO ON THE NOWRUZ TABLE, BUT NOT AN 'S'","colour":"p","tiles":["GOLDFISH","MIRROR","CANDLES","DIVAN OF HAFEZ"],"note":"The mirror for light, the candles for fire, the goldfish for life — and Hafez, opened at random on the night, to tell you how your year will go."}],"epilogue":"The whole board sits on one table, which is the joke: eight of these things are laid out together every March and the only thing separating them is a letter of the alphabet. Say each word out loud and the sin group announces itself."},
{"id":2,"title":"Tehrangeles","diff":2,"groups":[{"name":"WHAT THE DIASPORA CALLS ITS OWN SUBURBS","colour":"y","tiles":["TEHRANGELES","TEHRANTO","WESTWOOD","GREAT NECK"],"note":"Westwood Boulevard in Los Angeles is signposted Persian Square; North York earned Tehranto; Great Neck on Long Island is where much of the Iranian-Jewish community landed after 1979."},{"name":"PERSIAN BREADS","colour":"g","tiles":["SANGAK","BARBARI","LAVASH","TAFTOON"],"note":"Sangak is baked on a bed of hot pebbles and arrives with a few still in it; barbari is the thick breakfast one; lavash is thin enough to read through."},{"name":"PERSIAN DAIRY AND PICKLES","colour":"b","tiles":["DOOGH","KASHK","MAST-O-KHIAR","TORSHI"],"note":"Doogh is salted yogurt soda with mint, kashk is dried whey you spoon over aubergine, mast-o-khiar is yogurt and cucumber, and torshi is whatever the household pickled last autumn."},{"name":"LAID OUT FOR TEA","colour":"p","tiles":["SAMOVAR","ESTEKAN","QAND","GHALYAN"],"note":"The samovar that is never off, the little waisted glass, the sugar cube you hold between your teeth and drink the tea through, and the water pipe somebody's uncle is filling on the balcony."}],"epilogue":"Nothing on this board is ancient — it is a shopping list and a street map for people who left. The two double-fits both fail on arithmetic: SANGAK, BARBARI and TAFTOON are three breads looking for a fourth, and SAMOVAR, ESTEKAN, QAND and GHALYAN are already a full tray."},
{"id":3,"title":"The Poets","diff":3,"groups":[{"name":"CLASSICAL PERSIAN POETS","colour":"y","tiles":["HAFEZ","SAADI","RUMI","FERDOWSI"],"note":"Ferdowsi spent about thirty years on the Shahnameh and is credited with saving the Persian language from being written out of existence."},{"name":"THE BOOKS THEY WROTE","colour":"g","tiles":["DIVAN","GOLESTAN","MASNAVI","SHAHNAMEH"],"note":"Hafez's Divan, Saadi's Golestan ('rose garden'), Rumi's Masnavi, Ferdowsi's Shahnameh ('book of kings'). Four books, one shelf, most Iranian homes."},{"name":"PERSIAN POETIC FORMS","colour":"b","tiles":["GHAZAL","RUBAI","QASIDA","DOBEYTI"],"note":"The ghazal is the love lyric, the rubai the four-line epigram Khayyam made famous in English, the qasida the long formal ode, the dobeyti the folk couplet."},{"name":"CITIES WITH A POET'S TOMB","colour":"p","tiles":["SHIRAZ","TUS","KONYA","NISHAPUR"],"note":"Hafez AND Saadi in Shiraz, Ferdowsi at Tus, Rumi at Konya in Turkey, Khayyam at Nishapur. Iranians visit these the way other countries visit battlefields."}],"epilogue":"Rumi's book is called The Masnavi because it is written in masnavi form, and Hafez's book is called The Divan because a divan is what a collection is called. The titles ARE the forms. GHAZAL, RUBAI, QASIDA and DOBEYTI have no such double life, so let them fill the form group first."},
{"id":4,"title":"At the Sofreh","diff":2,"groups":[{"name":"KEBABS","colour":"y","tiles":["KOOBIDEH","BARG","JOOJEH","SOLTANI"],"note":"Koobideh is minced and pounded, barg is a thin fillet, joojeh is chicken in saffron and lemon, and soltani is one skewer of each because you couldn't decide."},{"name":"PERSIAN STEWS","colour":"g","tiles":["GHORMEH SABZI","FESENJAN","GHEYMEH","KHORESH-E BEH"],"note":"Ghormeh sabzi is the national dish and the one every family swears their mother makes best. Fesenjan is walnut and pomegranate, sweet and sour and dark as ink."},{"name":"RICE DISHES","colour":"b","tiles":["TAHCHIN","ZERESHK POLO","BAGHALI POLO","ADAS POLO"],"note":"Polo means the rice is cooked with something in it; the real prize is tahdig, the crust at the bottom, over which families have genuinely fallen out."},{"name":"PERSIAN SWEETS","colour":"p","tiles":["GAZ","SOHAN","BAMIEH","ZOOLBIA"],"note":"Gaz is Isfahan's nougat, sohan is Qom's saffron brittle, and zoolbia and bamieh are the syrup-soaked pair that appear in every Ramadan window."}],"epilogue":"BAMIEH is a sweet named after a vegetable that names a stew, which is the most Persian sentence on this board. GAZ, SOHAN and ZOOLBIA have no such ambiguity, and the stew group is full before you get there."},
{"id":5,"title":"The Map","diff":2,"groups":[{"name":"IRANIAN CITIES","colour":"y","tiles":["ISFAHAN","SHIRAZ","TABRIZ","MASHHAD"],"note":"'Isfahan is half the world' was a 17th-century boast and, standing in Naqsh-e Jahan square, still a defensible one."},{"name":"IRAN'S NEIGHBOURS","colour":"g","tiles":["IRAQ","ARMENIA","PAKISTAN","TURKMENISTAN"],"note":"Seven land borders in all: Iraq, Turkey, Armenia, Azerbaijan, Turkmenistan, Afghanistan and Pakistan."},{"name":"PERSIAN DYNASTIES","colour":"b","tiles":["ACHAEMENID","SASSANID","SAFAVID","QAJAR"],"note":"Achaemenid from Cyrus, Sassanid until the Arab conquest, Safavid who made Iran Shia and built Isfahan, Qajar who lost the Caucasus and invented Iranian photography."},{"name":"IRAN'S WATERS AND DESERTS","colour":"p","tiles":["CASPIAN","DASHT-E KAVIR","LUT","PERSIAN GULF"],"note":"The Lut recorded a land-surface temperature of about 70°C by satellite, among the hottest ever measured anywhere on Earth."}],"epilogue":"Four flat categories and no tricks — this one is a geography lesson wearing a puzzle's clothes. If you know that Armenia and Iran share a short mountain border, everything else falls out."},
{"id":6,"title":"Words You Already Use","diff":4,"groups":[{"name":"PERSIAN LOANWORDS YOU WEAR","colour":"y","tiles":["PYJAMAS","SHAWL","KHAKI","TURBAN"],"note":"Pay-jama, 'leg garment'. Shal. Khak, 'dust'. Dulband, the cloth you wind round a head."},{"name":"PERSIAN LOANWORDS YOU EAT OR DRINK","colour":"g","tiles":["JULEP","SPINACH","PISTACHIO","CANDY"],"note":"Golab (rosewater) became julep; esfanaj became spinach; pesteh became pistachio; qand, a lump of crystallised sugar, became candy."},{"name":"PERSIAN LOANWORDS THAT GROW OR GLOW","colour":"b","tiles":["LILAC","TULIP","JASMINE","AZURE"],"note":"Nilak the bluish one, yasmin the flower, lazhward the lapis stone that gave Europe both azure and ultramarine — and tulip, from dulband again, because the flower looks like a turban."},{"name":"PERSIAN LOANWORDS NOBODY EXPECTS","colour":"p","tiles":["PARADISE","CHECKMATE","MAGIC","MUMMY"],"note":"Pairidaeza, a walled garden. Shah mat, 'the king is helpless'. Magush, the Zoroastrian priest-caste the Greeks called magoi. And mum, wax — what Persian embalming used."}],"epilogue":"Every tile on this board is an English word that came from Persian, so the categories are four different reasons for the same fact. TULIP and TURBAN are the same Persian word arriving twice, six hundred years apart, which is the sort of thing that happens when a language is old enough."},
{"id":7,"title":"Knots and Strings","diff":3,"groups":[{"name":"PERSIAN MUSICAL INSTRUMENTS","colour":"y","tiles":["TAR","SANTUR","KAMANCHEH","TOMBAK"],"note":"The tar's body is two joined bowls covered in lambskin; the santur is struck with tiny wooden hammers; the kamancheh is bowed and stands on a spike."},{"name":"CARPET-WEAVING CITIES","colour":"g","tiles":["TABRIZ","KASHAN","KERMAN","NAIN"],"note":"You can date and place a Persian carpet from its knot count and palette alone — Nain is famously fine, Tabriz famously dense."},{"name":"PERSIAN CRAFTS","colour":"b","tiles":["KHATAM","MINAKARI","GHALAMZANI","TERMEH"],"note":"Khatam is micro-mosaic marquetry, minakari is enamel on copper, ghalamzani is hammer-and-chisel engraving, termeh is the woven wool that predates paisley."},{"name":"MOTIFS IN A PERSIAN CARPET","colour":"p","tiles":["BOTEH","GOL","MEDALLION","TREE OF LIFE"],"note":"The boteh is the teardrop the Scottish town of Paisley copied and got the credit for. The central medallion is the toranj."}],"epilogue":"Two of these groups are made by hand in the same workshops and one of them is played in the next room, which is why the board feels blurrier than it is. Nothing here fits twice — the difficulty is purely in knowing which craft is which."},
{"id":8,"title":"Two Thousand Years","diff":3,"groups":[{"name":"PERSIAN KINGS","colour":"y","tiles":["CYRUS","DARIUS","XERXES","SHAPUR"],"note":"Cyrus's cylinder is often called the first charter of its kind; Shapur I captured a Roman emperor alive and carved it into a cliff at Naqsh-e Rostam."},{"name":"CAPITALS OF PERSIAN EMPIRES","colour":"g","tiles":["PERSEPOLIS","CTESIPHON","PASARGADAE","SUSA"],"note":"Pasargadae was Cyrus's, Persepolis the ceremonial one Alexander burned, Susa the administrative workhorse, Ctesiphon the Parthian and Sasanian seat on the Tigris."},{"name":"ANCIENT PERSIAN ENGINEERING","colour":"b","tiles":["QANAT","YAKHCHAL","BADGIR","CHAHAR BAGH"],"note":"A qanat carries groundwater tens of kilometres underground by gravity alone; a yakhchal made and kept ice in the desert; a badgir is a tower that air-conditions a house with no power at all."},{"name":"ZOROASTRIAN WORDS","colour":"p","tiles":["AHURA MAZDA","AVESTA","FARAVAHAR","ATASHKADEH"],"note":"Ahura Mazda the wise lord, the Avesta the scripture, the faravahar the winged figure now worn as a necklace by half the diaspora, and the atashkadeh where the fire is kept."}],"epilogue":"The engineering group is the one modern Iran is proudest of and the one outsiders know least: QANAT, YAKHCHAL and BADGIR are all climate technology a thousand years early. ATASHKADEH is a building too, but it belongs to the faith that built it."},
{"id":9,"title":"Tehran","diff":4,"groups":[{"name":"TEHRAN LANDMARKS","colour":"y","tiles":["AZADI TOWER","MILAD TOWER","TABIAT BRIDGE","GRAND BAZAAR"],"note":"Azadi was built in 1971 and has been the backdrop to every side of every argument since. Tabiat is a three-level pedestrian bridge designed by Leila Araghian, who was 26."},{"name":"MOUNTAINS ABOVE THE CITY","colour":"g","tiles":["DAMAVAND","ALBORZ","TOCHAL","DARBAND"],"note":"Damavand is 5,610 m, the highest peak in the Middle East, and in the Shahnameh it is where Fereydun chains Zahhak."},{"name":"IRANIAN FILMMAKERS","colour":"b","tiles":["KIAROSTAMI","FARHADI","PANAHI","MAKHMALBAF"],"note":"Kiarostami took the Palme d'Or in 1997, Farhadi has two foreign-language Oscars, and Panahi has made several films while banned from making films."},{"name":"PERSIAN FAMILY WORDS","colour":"p","tiles":["MADAR","PEDAR","KHAHAR","BARADAR"],"note":"Mother, father, sister, brother — and if you look at them long enough you can see the Indo-European family resemblance to the English ones."}],"epilogue":"TOCHAL is the argument: it is a peak with a tourist attraction bolted to it. DAMAVAND, ALBORZ and DARBAND are unarguably geology, and AZADI TOWER, MILAD TOWER, TABIAT BRIDGE and GRAND BAZAAR are unarguably built, so the mountain keeps its rock."},
{"id":10,"title":"Rose and Nightingale","diff":4,"groups":[{"name":"DASTGAH — THE PERSIAN MUSICAL MODES","colour":"y","tiles":["SHUR","MAHUR","HOMAYUN","SEGAH"],"note":"Seven dastgah and five avaz between them cover the whole classical repertoire. Shur is the melancholy one and by far the most used."},{"name":"GREAT IRANIAN SINGERS","colour":"g","tiles":["SHAJARIAN","GOOGOOSH","BANAN","DELKASH"],"note":"Shajarian's 'Rabbana' is played every Ramadan; Googoosh was the pop star of a whole era and then did not sing in public for twenty-one years."},{"name":"SUFI WORDS YOU'D HEAR IN PERSIAN","colour":"b","tiles":["SAMA","FANA","ISHQ","DERVISH"],"note":"Sama is the listening-and-turning ceremony, fana the annihilation of the self, ishq the love that causes it, dervish the one who has given up owning things."},{"name":"THE STOCK IMAGES OF A GHAZAL","colour":"p","tiles":["ROSE","NIGHTINGALE","WINE","MOTH"],"note":"Gol and bolbol, the rose and the nightingale who loves her hopelessly; the wine that may or may not be actual wine; the moth who flies into the candle on purpose."}],"epilogue":"Persian poetry and Persian mysticism use the same words on purpose, so WINE genuinely belongs to two worlds — that ambiguity is the art form, not a bug in the puzzle. The clean line is language: SAMA, FANA, ISHQ and DERVISH are Persian words carried into English, and ROSE, NIGHTINGALE, WINE and MOTH are plain English nouns doing symbolic work."},
{"id":11,"title":"The Kitchen Table","diff":4,"groups":[{"name":"PERSIAN INGREDIENTS ON AN AMERICAN SHELF","colour":"y","tiles":["SAFFRON","BARBERRIES","ROSEWATER","POMEGRANATE"],"note":"Saffron is bloomed in hot water first, never sprinkled dry; barberries are fried in butter for thirty seconds and no longer or they turn black."},{"name":"PERSIAN NAMES THAT MEAN A FLOWER","colour":"g","tiles":["YASMIN","NILOOFAR","LALEH","GOLNAR"],"note":"Jasmine, water lily, tulip, and pomegranate blossom. Persian first names are frequently just the nicest noun available."},{"name":"ON THE SOFREH AQD","colour":"b","tiles":["MIRROR","CANDELABRA","ESFAND","HONEY"],"note":"The bride sees her groom first in the mirror; esfand seeds burn against the evil eye; the couple feed each other honey so the marriage starts sweet."},{"name":"WHAT THEY ACTUALLY SAY TO YOU","colour":"p","tiles":["GHORBOONET","JOON","AZIZAM","TAAROF"],"note":"'May I be sacrificed for you' as a casual goodbye; 'joon' after your name as affection; 'azizam' for my dear; and taarof, the ritual refusal that everybody performs and nobody means."}],"epilogue":"This board is somebody's actual house. ROSEWATER and ESFAND live in two rooms of it at once, which is why the resolution has to come from the tiles that don't: SAFFRON, BARBERRIES and POMEGRANATE are groceries, MIRROR, CANDELABRA and HONEY are wedding, and the rest sorts itself."},
{"id":12,"title":"Count to Four","diff":5,"groups":[{"name":"COLOURS IN PERSIAN","colour":"y","tiles":["SEFID","SIYAH","SORKH","ABI"],"note":"White, black, red, blue. Abi comes from ab, water — the same ab as the -jab in Punjab, which is panj-ab, five rivers."},{"name":"PERSIAN WORDS FOR POWER","colour":"g","tiles":["SHAH","SHAHANSHAH","VIZIER","SATRAP"],"note":"King, king of kings, the minister who runs everything, and the provincial governor whose title the Greeks borrowed and never gave back."},{"name":"CREATURES OF PERSIAN MYTH","colour":"b","tiles":["SIMORGH","DIV","PERI","HOMA"],"note":"The Simorgh is a benevolent giant bird; a div is a demon; a peri is where the word 'fairy' partly comes from; the homa never lands and whoever its shadow falls on becomes king."},{"name":"COUNT TO FOUR IN PERSIAN","colour":"p","tiles":["YEK","DO","SE","CHAHAR"],"note":"Yek, do, se, chahar. 'Do' is two, which is why Chaharshanbe is the fourth day and the bonfire night is the last one of the year."}],"epilogue":"The hardest board in the pack, and the way in is the smallest tiles: YEK, DO, SE and CHAHAR are two and three letters long and mean nothing in English, which is exactly the shape of a purple. The colours next door are the same size and the same everyday register, which is the real trap — but no colour is a number, and once the count is out the rest lines up behind it."}
]},
{"id":"united","name":"RED DEVILS","blurb":"Old Trafford and the Premier League. The FOURMATIONS archive, rehoused.","boards":[
{"id":1,"title":"Home Ground","diff":1,"groups":[{"name":"MANCHESTER BANDS","colour":"y","tiles":["OASIS","THE SMITHS","JOY DIVISION","NEW ORDER"],"note":"Joy Division became New Order after Ian Curtis died in 1980 — technically half a group, and the only reason both fit."},{"name":"SIR ALEX FERGUSON MANAGED THEM","colour":"g","tiles":["EAST STIRLING","ST MIRREN","ABERDEEN","SCOTLAND"],"note":"East Stirlingshire in 1974 with eight players and no goalkeeper. Aberdeen broke the Old Firm and beat Real Madrid. Scotland he took to Mexico '86 after Jock Stein died at Ninian Park."},{"name":"UNITED'S HOME GROUNDS","colour":"b","tiles":["NORTH ROAD","BANK STREET","OLD TRAFFORD","MAINE ROAD"],"note":"North Road 1878, Bank Street 1893, Old Trafford 1910 — and Maine Road from 1946 to 1949, because the Luftwaffe had flattened Old Trafford and City lent them the ground."},{"name":"MANCHESTER PLACES","colour":"p","tiles":["CURRY MILE","CANAL STREET","THE HACIENDA","DEANSGATE"],"note":"The Haçienda was funded by New Order's record sales and lost money on every pint it ever sold. FAC 51, 1982 to 1997."}],"epilogue":"The gentlest board in the pack and it still has a sting: two of the grounds are also just places in Manchester, and one of them belonged to City. Count the venues United actually played home matches at — there are exactly four, and the Haçienda is not one of them."},
{"id":2,"title":"Numbers Up","diff":2,"groups":[{"name":"UNITED'S RECORD APPEARANCE MAKERS","colour":"y","tiles":["GIGGS","CHARLTON","SCHOLES","FOULKES"],"note":"963, 758, 718, 688. Giggs's total is not going to be beaten by anybody, ever, in any sport, in this country."},{"name":"WORE UNITED'S NO. 10","colour":"g","tiles":["ROONEY","SHERINGHAM","VAN NISTELROOY","RASHFORD"],"note":"Squad numbers only arrived in 1993–94. Since then the 10 has been a striker's shirt without exception."},{"name":"PLAYED IN THE 1968 EUROPEAN CUP FINAL","colour":"b","tiles":["STILES","CRERAND","ASTON","DUNNE"],"note":"Wembley, 4–1 after extra time, ten years and three months after Munich. John Aston had the game of his life on the left wing and nobody remembers."},{"name":"___ CARD","colour":"p","tiles":["RED","WILD","POST","FLASH"],"note":"Red card, wildcard, postcard, flashcard. Only one of them gets you an early bath."}],"epilogue":"Two men played in 1968 and are also in the all-time top four, which is not a coincidence — that is what a career at one club looks like. STILES, CRERAND, ASTON and DUNNE have only one qualification between them, so the final fills itself and the appearance list takes the leftovers."},
{"id":3,"title":"The Caretakers","diff":2,"groups":[{"name":"UNITED'S KIT MANUFACTURERS","colour":"y","tiles":["ADMIRAL","ADIDAS","UMBRO","NIKE"],"note":"Admiral 1975, Adidas 1980, Umbro 1992, Nike 2002, Adidas again from 2015. The 1992 Umbro deal outfitted the first Premier League title in 26 years."},{"name":"TOOK CHARGE OF UNITED IN A CARETAKER OR INTERIM SPELL","colour":"g","tiles":["GIGGS","CARRICK","RANGNICK","VAN NISTELROOY"],"note":"Giggs after Moyes in 2014, Carrick after Solskjær in 2021, Rangnick for the rest of that season, Van Nistelrooy for four games in 2024. Carrick won two and drew one and left."},{"name":"BEAT UNITED IN AN FA CUP FINAL","colour":"b","tiles":["SOUTHAMPTON","EVERTON","CHELSEA","MAN CITY"],"note":"Southampton 1976 (Bobby Stokes, second division), Everton 1995, Chelsea twice, City in 2023 — the first all-Manchester final in the competition's history."},{"name":"UNITED NICKNAMES","colour":"p","tiles":["SPARKY","CHOCCY","THE GUV'NOR","WAZZA"],"note":"Mark Hughes, Brian McClair, Paul Ince and Wayne Rooney. Ince gave himself his; that is the entire personality of Paul Ince."}],"epilogue":"No double agents on this one — the difficulty is entirely in knowing that Rangnick's title was 'interim manager' and Carrick's lasted three matches. If the nicknames went last, that is the correct order of operations."},
{"id":4,"title":"Bloodlines","diff":3,"groups":[{"name":"UNITED'S DUTCHMEN","colour":"y","tiles":["BLIND","DE LIGT","WEGHORST","DEPAY"],"note":"Daley Blind's father Danny won the European Cup with Ajax; Daley won the Europa League with United in 2017."},{"name":"SCOTS AT OLD TRAFFORD","colour":"g","tiles":["MCCLAIR","MCTOMINAY","DENIS LAW","FLETCHER"],"note":"McClair scored 24 in his first season, the first United player past 20 since Best. Law is still the only Scot to win the Ballon d'Or."},{"name":"CAME THROUGH UNITED'S ACADEMY","colour":"b","tiles":["RASHFORD","MAINOO","WELBECK","WES BROWN"],"note":"United have named an academy graduate in every matchday squad since October 1937 — the longest unbroken run in English football."},{"name":"OLD ___","colour":"p","tiles":["TRAFFORD","FIRM","MASTER","TIMER"],"note":"Old Trafford, Old Firm, old master, old timer. Only one of them is a ground, and it isn't the one in Glasgow."}],"epilogue":"Two Scots are also academy boys, which is what happens when a club scouts north of the border for a hundred years. RASHFORD, MAINOO, WELBECK and WES BROWN can only be one thing, so the academy is full before the Scots even sit down."},
{"id":5,"title":"Those Other Nights in Europe","diff":3,"groups":[{"name":"UNITED'S EUROPEAN CUP FINAL OPPONENTS","colour":"y","tiles":["BENFICA","BAYERN","CHELSEA","BARCELONA"],"note":"Benfica 1968, Bayern 1999, Chelsea 2008, Barcelona 2009 and 2011. Two won, three lost — and Barcelona did it twice, which still stings."},{"name":"SCORED FOR UNITED IN A EUROPEAN FINAL","colour":"g","tiles":["BEST","KIDD","SHERINGHAM","RONALDO"],"note":"Best and Kidd in extra time at Wembley in '68 — Kidd on his 19th birthday. Sheringham in Barcelona, Ronaldo with a header in the Moscow rain."},{"name":"IN UNITED'S EUROPEAN TROPHY CABINET","colour":"b","tiles":["EUROPEAN CUP","EUROPA LEAGUE","UEFA SUPER CUP","CLUB WORLD CUP"],"note":"Three European Cups, the 1991 Cup Winners' Cup and Super Cup, the 1999 Intercontinental, the 2008 Club World Cup, and Mourinho's Europa League in 2017."},{"name":"___ CUP","colour":"p","tiles":["BUTTER","HIC","TEA","EGG"],"note":"Buttercup, hiccup, teacup, egg cup. None of them has ever been paraded round Deansgate on an open-top bus."}],"epilogue":"Four groups, three of them about silverware, and the last one about a flower and a spasm of the diaphragm. The purple is a relief valve — after three rows of European history, the answer is that CUP was never the point."},
{"id":6,"title":"Word on the Shirt","diff":4,"groups":[{"name":"UNITED MEN WITH A WORLD CUP WINNER'S MEDAL","colour":"y","tiles":["STILES","SCHWEINSTEIGER","POGBA","L. MARTÍNEZ"],"note":"Stiles won his at United in 1966; Schweinsteiger arrived with his in 2015; Pogba won his as a United player in 2018; Lisandro Martínez had been at the club four months when Argentina won in 2022."},{"name":"COLOURS IN THE SURNAME","colour":"g","tiles":["BLACKMORE","WHITESIDE","GREENHOFF","BROWN"],"note":"Clayton Blackmore, Norman Whiteside, the Greenhoff brothers and Wes Brown — a full paint chart, all of them genuinely United."},{"name":"UNITED SURNAMES THAT ARE ORDINARY WORDS","colour":"b","tiles":["BUTT","PARK","BLIND","MAY"],"note":"Nicky Butt, Park Ji-sung, Daley Blind, David May. Read the team sheet as a sentence and it nearly works."},{"name":"ON THE MANCHESTER UNITED CREST","colour":"p","tiles":["SHIP","TRIDENT","RED DEVIL","FOOTBALLS"],"note":"The ship comes from Manchester's city arms and the Ship Canal; the devil arrived in the 1960s from the rugby league nickname Busby borrowed."}],"epilogue":"BROWN is the honest double-fit: a colour AND a word you'd find in a dictionary. The resolution is that BLACKMORE, WHITESIDE and GREENHOFF are not words, so the colour group needs BROWN more than the word group does — and BUTT, PARK and BLIND make four on their own."},
{"id":7,"title":"Crossing the Line","diff":4,"groups":[{"name":"PLAYED FOR UNITED AND LIVERPOOL","colour":"y","tiles":["MICHAEL OWEN","PAUL INCE","BEARDSLEY","CHISNALL"],"note":"Phil Chisnall in 1964 is still the last player transferred directly between the two clubs. Beardsley played one match for United, in a League Cup tie in 1982, and was sold."},{"name":"UNITED OLD BOYS IN THE PUNDIT'S CHAIR","colour":"g","tiles":["KEANE","SCHOLES","RIO FERDINAND","G. NEVILLE"],"note":"Keane's job is to be appalled, Neville's is to explain why, Ferdinand's is to laugh, and Scholes's is to say four words and leave."},{"name":"SURVIVED MUNICH AND PLAYED FOR UNITED AGAIN","colour":"b","tiles":["BOBBY CHARLTON","BILL FOULKES","HARRY GREGG","DENNIS VIOLLET"],"note":"6 February 1958. Gregg went back into the burning aircraft twice and pulled out a baby and her mother. Viollet came back and scored 32 league goals in 1959–60, still a club record."},{"name":"___ FORD","colour":"p","tiles":["TRAF","OX","BED","SAL"],"note":"Trafford, Oxford, Bedford, Salford — and Salford City is the one the Class of '92 bought."}],"epilogue":"MICHAEL OWEN is a pundit and a man who played for both, and the pundit chair only seats four. KEANE, SCHOLES, RIO FERDINAND and G. NEVILLE never wore red and Liverpool red, so they get the studio and Owen gets the awkward CV."},
{"id":8,"title":"Full Time","diff":5,"groups":[{"name":"BEATEN BY UNITED IN A LEAGUE CUP FINAL","colour":"y","tiles":["NOTTM FOREST","WIGAN","SPURS","NEWCASTLE"],"note":"1992, 2006, 2009, 2023. The 1992 win over Forest was United's first League Cup and Brian Clough's last final."},{"name":"UNITED'S ARGENTINES","colour":"g","tiles":["VERÓN","HEINZE","GARNACHO","ROJO"],"note":"Verón cost £28.1m in 2001 and confused everybody including himself. Rojo scored maybe three goals and one of them was a 93rd-minute winner in the Champions League."},{"name":"WON THE BALLON D'OR AS A UNITED PLAYER","colour":"b","tiles":["LAW","CHARLTON","BEST","RONALDO"],"note":"1964, 1966, 1968 — three in five years, the Holy Trinity in order — and then a gap of forty years until Ronaldo in 2008."},{"name":"___ RED","colour":"p","tiles":["CODE","INFRA","SEEING","BLOOD"],"note":"Code red, infrared, seeing red, blood red. Four kinds of alarm and not one of them a football club."}],"epilogue":"The hardest board in the pack, and both traps are language rather than football: CHARLTON reads as a club and ROJO reads as a colour. Neither can move, because NOTTM FOREST, WIGAN, SPURS and NEWCASTLE are already four, and so are CODE, INFRA, SEEING and BLOOD. Verón would have been proud of the misdirection and baffled by the execution."},
{"id":9,"title":"Fergie Time","diff":2,"groups":[{"name":"PHRASES SIR ALEX GAVE THE LANGUAGE","colour":"y","tiles":["HAIRDRYER","SQUEAKY BUM","THEIR PERCH","BLOODY HELL"],"note":"The hairdryer was delivered from about six inches away; 'squeaky bum time' arrived in 2003; the perch was Liverpool's, and knocking them off it was his stated life's work; 'Football, bloody hell' was all he could manage in Barcelona in 1999."},{"name":"MANAGED UNITED BEFORE FERGUSON","colour":"g","tiles":["BUSBY","DOCHERTY","SEXTON","ATKINSON"],"note":"Busby to 1969, Docherty to 1977 — sacked for the relationship, not the results — Sexton to 1981, Atkinson to 1986. Four men in the seventeen years before the twenty-six."},{"name":"UNITED'S FIRST PREMIER LEAGUE CHAMPIONS, 1993","colour":"b","tiles":["BRUCE","PALLISTER","KANCHELSKIS","SHARPE"],"note":"Twenty-six years without a league title ended in May 1993, in a season where Bruce and Pallister played nearly every minute and Ferguson had just paid Leeds £1.2m for Cantona."},{"name":"___ TIME","colour":"p","tiles":["FERGIE","EXTRA","PART","BIG"],"note":"Fergie time, extra time, part time, big time. Only one of them was measured by a stopwatch that was allegedly running slow."}],"epilogue":"A calibration board with one nasty little idea in it: two groups are surnames and the surnames look interchangeable, so the question is who held a clipboard and who wore a shirt. BUSBY, DOCHERTY, SEXTON and ATKINSON are four managers already, which is what keeps Steve Bruce in the 1993 side where he belongs."},
{"id":10,"title":"Passport Photos","diff":3,"groups":[{"name":"UNITED'S BRAZILIANS","colour":"y","tiles":["KLEBERSON","ANDERSON","FRED","CASEMIRO"],"note":"Kleberson arrived a world champion in 2003 and left in 2005; Anderson cost more than Nani and is remembered mainly for laughing; Casemiro arrived with five Champions Leagues in his suitcase."},{"name":"UNITED'S FRENCHMEN","colour":"g","tiles":["EVRA","MARTIAL","VARANE","POGBA"],"note":"Evra played 379 games and never stopped talking; Martial was 19 and cost £36m and scored on his debut against Liverpool, which bought him about four years of patience."},{"name":"KEPT GOAL FOR UNITED","colour":"b","tiles":["BARTHEZ","HOWARD","ROMERO","LINDEGAARD"],"note":"Barthez won a World Cup and a Champions League before he arrived and still spent two years being described as eccentric; Romero played 61 games in six seasons and lost none of the finals he was allowed near."},{"name":"DE ___","colour":"p","tiles":["GEA","LIGT","BOER","JONG"],"note":"De Gea, De Ligt, De Boer, De Jong. Dutch prefixes and one Spanish one, all of them a goalkeeper or a defender or a midfielder United have owned or wanted."}],"epilogue":"Three groups of surnames and one group of prefixes, so the tell is length: GEA, LIGT, BOER and JONG are all too short to be anybody. BARTHEZ is the real double-fit — French AND a United keeper — and the four-man French group has no room for him, which is the only reason he ends up filed under gloves."},
{"id":11,"title":"The Ninety-Two","diff":3,"groups":[{"name":"HAVE WON THE PREMIER LEAGUE","colour":"y","tiles":["BLACKBURN","LEICESTER","ARSENAL","MAN CITY"],"note":"Seven clubs have won it in total. Blackburn spent Jack Walker's money in 1995, Leicester spent nothing in 2016, and nobody has since done anything as unlikely as either."},{"name":"HAVE NEVER PLAYED A PREMIER LEAGUE SEASON","colour":"g","tiles":["MILLWALL","PRESTON","PLYMOUTH","WREXHAM"],"note":"Preston were English football's first champions in 1889 and have not been in the top flight since 1961. Wrexham are the third-oldest professional club in the world and have never been higher than the second tier."},{"name":"THE CLUB'S ORIGINAL NAME","colour":"b","tiles":["NEWTON HEATH","DIAL SQUARE","SMALL HEATH","ST DOMINGO"],"note":"Newton Heath became United in 1902, Dial Square became Arsenal, Small Heath became Birmingham City, and St Domingo — a church football team — became Everton."},{"name":"___ ROVERS","colour":"p","tiles":["TRANMERE","DONCASTER","RAITH","FOREST GREEN"],"note":"Tranmere, Doncaster, Raith in Kirkcaldy and Forest Green in Gloucestershire, who are vegan and play on an organic pitch."}],"epilogue":"Every tile is a football club, so nothing sorts itself and everything has to be known. BLACKBURN is the double-fit worth admiring — champion and Rover — and it is pinned by counting: TRANMERE, DONCASTER, RAITH and FOREST GREEN are four Rovers already, so the 1995 champions keep their man."},
{"id":12,"title":"Theatre of Dreams","diff":3,"groups":[{"name":"YOU WALK PAST THESE AT OLD TRAFFORD","colour":"y","tiles":["THE TRINITY","MUNICH CLOCK","BUSBY WAY","SIR ALEX STAND"],"note":"The Trinity is Best, Law and Charlton in bronze, facing the stand named after the man who came after them. The Munich clock has read 6 February 1958, 3.04pm, since the year it happened."},{"name":"SUNG AT OLD TRAFFORD","colour":"g","tiles":["GLORY GLORY","VIVA RONALDO","TEAR YOU APART","TWELVE DAYS"],"note":"'Giggs will tear you apart again' is Joy Division, borrowed from a band that played four miles away; the Twelve Days of Cantona is a Christmas carol with one gift in it."},{"name":"PARTS OF AN OLD ENGLISH GROUND","colour":"b","tiles":["TERRACE","TUNNEL","DUGOUT","PADDOCK"],"note":"The paddock was the standing strip in front of the main stand, and the terraces went after Hillsborough and the Taylor Report — which is why the singing moved and got quieter."},{"name":"___ END","colour":"p","tiles":["STRETFORD","WEEK","BOOK","DEAD"],"note":"Stretford End, weekend, bookend, dead end. The first one is where the noise came from and, for about thirty years, where you stood if you meant it."}],"epilogue":"Two groups about one stadium, one about all stadiums, and one about none of them. STRETFORD is the trap the board is built on: it is Old Trafford furniture AND a compound-word stem, and it goes purple because THE TRINITY, MUNICH CLOCK, BUSBY WAY and SIR ALEX STAND are already four things you can stand in front of."},
{"id":13,"title":"Women in Red","diff":3,"groups":[{"name":"PLAYED FOR MANCHESTER UNITED WOMEN","colour":"y","tiles":["EARPS","TOONE","ZELEM","GALTON"],"note":"United only founded a women's team in 2018, which makes Katie Zelem — captain from almost the start — the closest thing the side has to a Foulkes."},{"name":"ENGLAND'S EURO 2022 WINNERS","colour":"g","tiles":["BRONZE","WILLIAMSON","HEMP","STANWAY"],"note":"Wembley, 87,192 people, extra time, Chloe Kelly's shirt over her head. It remains the only major tournament any England senior side has won on home soil since 1966."},{"name":"ENGLAND WOMEN'S HEAD COACHES","colour":"b","tiles":["POWELL","SAMPSON","P. NEVILLE","WIEGMAN"],"note":"Hope Powell had the job for fifteen years and built the professional era; Wiegman won the Euros with two different countries, back to back."},{"name":"___ AGE","colour":"p","tiles":["STONE","ICE","NEW","OLD"],"note":"Stone age, ice age, new age, old age. Four eras and not one of them as short as the one this England team started."}],"epilogue":"Three of these tiles are double-agents and the resolution is arithmetic in both directions. BRONZE, WILLIAMSON, HEMP and STANWAY never played for United, so they are a complete Euro-winning group without EARPS or TOONE — and STONE, ICE, NEW and OLD are a complete set of ages without Lucy Bronze."},
{"id":14,"title":"The Interview","diff":3,"groups":[{"name":"PLAYED FOR UNITED, LATER MANAGED IN THE PREMIER LEAGUE","colour":"y","tiles":["HUGHES","INCE","STRACHAN","SOLSKJÆR"],"note":"Hughes managed five Premier League clubs, Ince took Blackburn, Strachan had Coventry and Southampton, and Solskjær kept Cardiff up for exactly no seasons before going home."},{"name":"MANAGED UNITED IN THE PREMIER LEAGUE ERA","colour":"g","tiles":["VAN GAAL","MOURINHO","TEN HAG","AMORIM"],"note":"Ferguson, Moyes, Van Gaal, Mourinho, Solskjær, Rangnick, Ten Hag, Amorim. Eight men since 1992 and five of them since 2013."},{"name":"NICKNAMED 'THE ___ ONE'","colour":"b","tiles":["SPECIAL","NORMAL","CHOSEN","HAPPY"],"note":"Mourinho called himself the Special One in 2004 and the Happy One in 2013; Klopp answered with the Normal One in 2015; the Stretford End hung a banner calling David Moyes the Chosen One and then took it down."},{"name":"HOW A MANAGER ACTUALLY LEAVES","colour":"p","tiles":["MUTUAL CONSENT","GARDEN LEAVE","P45","THE BULLET"],"note":"'Mutual consent' means the compensation was agreed; 'garden leave' means you are still being paid not to speak; a P45 is the actual British tax form, which is why the phrase stings."}],"epilogue":"Two groups of surnames, one of adjectives, one of euphemisms. SOLSKJÆR is the honest double-fit — he did both things — and VAN GAAL, MOURINHO, TEN HAG and AMORIM are four United managers without him, which is the whole resolution. If you tried the nicknames first you had the right idea and the wrong four."},
{"id":15,"title":"Deadline Day","diff":4,"groups":[{"name":"UNITED SIGNED THEM FROM ANOTHER PREMIER LEAGUE CLUB","colour":"y","tiles":["MAGUIRE","ERIKSEN","CUNHA","MBEUMO"],"note":"Maguire from Leicester in 2019 for £80m, Eriksen from Brentford on a free in 2022, Cunha from Wolves and Mbeumo from Brentford in the summer of 2025. Two of the four cost nothing but a wage."},{"name":"UNITED BUYS THE TERRACES STILL WINCE AT","colour":"g","tiles":["BEBÉ","TAIBI","DJEMBA-DJEMBA","KLEBERSON"],"note":"Bebé was signed for £7.4m having reportedly never been watched play; Taibi let a Le Tissier shot through his legs and hands in the same movement; Djemba-Djemba was so good they named him twice, in Ferguson's own joke."},{"name":"HELD THE WORLD TRANSFER RECORD","colour":"b","tiles":["FIGO","ZIDANE","POGBA","NEYMAR"],"note":"Figo 2000, Zidane 2001, Pogba 2016, Neymar 2017. Pogba's £89m was the highest fee ever paid by anyone at the time, for a player United had let leave for nothing four years earlier."},{"name":"___ WINDOW","colour":"p","tiles":["TRANSFER","BAY","SHOP","REAR"],"note":"Transfer window, bay window, shop window, Rear Window. The first one only exists because FIFA agreed in 2002 to stop clubs buying players in April."}],"epilogue":"Three groups of players, one of compound nouns, and two tiles that could sit in either of the first two groups depending on how you feel about 2019. BEBÉ, TAIBI, DJEMBA-DJEMBA and KLEBERSON are four undisputed answers, and that closes the argument: POGBA is a record fee and MAGUIRE is a Premier League purchase, and the wincing is left as an exercise for the reader."},
{"id":16,"title":"Sponsored By","diff":3,"groups":[{"name":"HAS BEEN ON THE FRONT OF A UNITED SHIRT","colour":"y","tiles":["SHARP","AON","TEAMVIEWER","SNAPDRAGON"],"note":"Sharp for eighteen years, then Vodafone, AIG, Aon, Chevrolet, TeamViewer and Snapdragon — the shirt has become a rolling advertisement for whichever industry is having a moment."},{"name":"ON SOMEBODY ELSE'S SHIRT IN THE EIGHTIES","colour":"g","tiles":["JVC","HOLSTEN","CANDY","CROWN PAINTS"],"note":"JVC on Arsenal, Holsten on Tottenham, Candy and then Crown Paints on Liverpool. Shirt sponsors were banned on television until 1983, which is why the older ones look so shy."},{"name":"AN ANIMAL ON THE BADGE","colour":"b","tiles":["LEICESTER","WOLVES","NORWICH","BRIGHTON"],"note":"A fox, a wolf's head, a canary and a seagull. Brighton's seagull arrived because the crowd started chanting 'Seagulls' back at Crystal Palace's 'Eagles' in the 1970s."},{"name":"___ SHIRT","colour":"p","tiles":["T","NIGHT","SWEAT","HAIR"],"note":"T-shirt, nightshirt, sweatshirt, hairshirt. Three garments and one medieval penance, which is also a fair description of some replica kits."}],"epilogue":"The joke is that two groups are brand names from the same drawer and the only difference is which chest they were printed on. SHARP, AON, TEAMVIEWER and SNAPDRAGON are the four United ones, so JVC and CANDY stay where they were sewn — and if you had the animals early, the badge group is the one part of this board that does not require a memory of the eighties."},
{"id":17,"title":"The Anthem","diff":4,"groups":[{"name":"ENGLISH CLUBS THAT HAVE WON THE EUROPEAN CUP","colour":"y","tiles":["LIVERPOOL","NOTTM FOREST","ASTON VILLA","MAN CITY"],"note":"Six English clubs in total. Forest won it twice with a squad assembled for less than the fee for one modern full-back, and Villa's 1982 win was their last trophy of any real size for forty years."},{"name":"ITALIAN CLUBS UNITED HAVE MET IN EUROPE","colour":"g","tiles":["JUVENTUS","MILAN","ROMA","ATALANTA"],"note":"United beat Roma 7-1 in 2007 and lost 3-0 to Milan in the same competition a month later, which tells you most of what you need to know about that team."},{"name":"LINES OF THE UEFA ANTHEM","colour":"b","tiles":["DIE MEISTER","DIE BESTEN","LES GRANDES","THE CHAMPIONS"],"note":"Written in 1992 by Tony Britten on a Handel coronation anthem, in German, French and English at once, so that no country could claim it — and so nobody knows more than four words of it."},{"name":"___ NET","colour":"p","tiles":["INTER","HAIR","SAFETY","SUB"],"note":"Internet, hairnet, safety net, subnet. Only one of them has a Champions League pedigree, and it is not the one you can wear."}],"epilogue":"INTER is the best trap in the pack: correct in every way except the one that counts. JUVENTUS, MILAN, ROMA and ATALANTA are four Italian opponents already, so Inter goes to the purple — and once you see that HAIR, SAFETY and SUB are all waiting for the same three letters, the whole board unlocks backwards."},
{"id":18,"title":"Derby Day","diff":4,"groups":[{"name":"MANCHESTER DERBY FOLKLORE","colour":"y","tiles":["WHY ALWAYS ME","THE 6-1","THE OVERHEAD","TYPICAL CITY"],"note":"Balotelli's shirt in 2011, the 6-1 at Old Trafford six weeks later, Rooney's overhead kick in 2011 that even City fans replay, and 'typical City' — a phrase City fans coined about themselves and then retired."},{"name":"WORE BOTH MANCHESTER SHIRTS","colour":"g","tiles":["SCHMEICHEL","BRIAN KIDD","TEVEZ","ANDY COLE"],"note":"Schmeichel played a season for City in 2002-03, which United fans have decided not to remember. Kidd played for both and coached both, and won the European Cup for one of them on his 19th birthday."},{"name":"DERBIES NAMED AFTER A RIVER OR A ROAD","colour":"b","tiles":["TYNE-WEAR","EAST ANGLIAN","M69","SEVERNSIDE"],"note":"Two rivers, a region, a motorway between Leicester and Coventry, and an estuary. When two clubs share nothing else, geography has to do the work."},{"name":"___ BLUE","colour":"p","tiles":["TRUE","BABY","NAVY","ROYAL"],"note":"True blue, baby blue, navy blue, royal blue. City play in sky, which is not on the list, which is the sort of detail this pack considers a joke."}],"epilogue":"TEVEZ is the tile that belongs in two places, and folklore loses because WHY ALWAYS ME, THE 6-1, THE OVERHEAD and TYPICAL CITY are already four moments. Everything else is a question of whether a proper noun is a person, a fixture or half a colour — and if you got the blues first, the rest is a Manchester history lesson."},
{"id":19,"title":"Feed the Big Man","diff":4,"groups":[{"name":"SLANG FOR A SPECTACULAR GOAL","colour":"y","tiles":["SCREAMER","WORLDIE","ROCKET","PILEDRIVER"],"note":"'Worldie' is the newest of the four and the only one that started on the internet; a piledriver is specifically a low one hit so hard the keeper hears it late."},{"name":"SKILL MOVES WITH A NAME","colour":"g","tiles":["NUTMEG","RABONA","PANENKA","ELASTICO"],"note":"The rabona is named after an Argentine magazine cartoon about playing truant; the panenka after the man who chipped a European Championship final penalty down the middle in 1976."},{"name":"WAYS OF SAYING 'HIT IT LONG'","colour":"b","tiles":["HOOF","PUNT","LAUNCH","LUMP"],"note":"Four verbs a commentator uses when a team has run out of ideas, and one of them — 'lump it' — is the only technical term in English football that is also an insult."},{"name":"___ KICK","colour":"p","tiles":["FREE","DROP","PLACE","BICYCLE"],"note":"Free kick, drop kick, place kick, bicycle kick. Three of them are in the laws of the game and one is in the highlights reel."}],"epilogue":"Three groups of football slang and one of compound nouns, which is why this board reads as blurry: everything is a kick of some kind. BICYCLE is the honest double-fit and it goes purple because NUTMEG, RABONA, PANENKA and ELASTICO are four named moves already — and because FREE, DROP and PLACE are three-quarters of a rulebook."},
{"id":20,"title":"After the Whistle","diff":5,"groups":[{"name":"HOSTING MATCHES AT THE 2026 WORLD CUP","colour":"y","tiles":["HOUSTON","BOSTON","TORONTO","MONTERREY"],"note":"Sixteen cities across three countries. Boston's matches are in Foxborough, forty minutes out of town, and Houston's are indoors with the roof shut and the air conditioning on."},{"name":"FOOTBALL CLUBS THAT DO NOT EXIST","colour":"g","tiles":["AFC RICHMOND","MELCHESTER","HARCHESTER","HOUNSLOW"],"note":"Ted Lasso's Richmond, Roy of the Rovers' Melchester, Dream Team's Harchester, and the Hounslow Harriers of Bend It Like Beckham — three of them have won more than United did in the 2010s."},{"name":"FOOTBALL COUNTS THESE IN FOURS","colour":"b","tiles":["BACK FOUR","FOUR-FOUR-TWO","QUADRUPLE","FOURTH ROUND"],"note":"The flat back four was English orthodoxy for forty years; nobody has ever won a quadruple in England; and the FA Cup fourth round is the one where the giant-killing usually happens."},{"name":"FULL ___","colour":"p","tiles":["TIME","ENGLISH","MOON","HOUSE"],"note":"Full time, full English, full moon, full house. One of them is how this pack ends and one of them is what you eat before an eleven o'clock kick-off."}],"epilogue":"The last board, and it is built out of places that may or may not exist. HOUNSLOW has a foot in both halves of it, and the fix is that HOUSTON, BOSTON, TORONTO and MONTERREY are unarguably hosting matches in 2026 — which leaves Hounslow with the Harriers. Two of those host cities are the players' own, which is the only reason this board exists."}
]},
{"id":"places","name":"FOUR CITIES","blurb":"Cambridge, London, Edinburgh, Houston. Squares, closes, bayous, feeder roads.","boards":[
{"id":1,"title":"The Red Line","diff":2,"groups":[{"name":"STOPS ON THE RED LINE","colour":"y","tiles":["ALEWIFE","DAVIS","ASHMONT","BRAINTREE"],"note":"Alewife at the north end, and the line splits after JFK/UMass into the Ashmont and Braintree branches — which is why the sign matters."},{"name":"BRIDGES OVER THE CHARLES","colour":"g","tiles":["LONGFELLOW","WEEKS","ELIOT","ANDERSON"],"note":"The Longfellow is the salt-and-pepper one that carries the Red Line; Weeks is the footbridge everyone photographs; Anderson takes JFK Street across to the stadium."},{"name":"HARVARD SQUARE INSTITUTIONS","colour":"b","tiles":["THE COOP","CLUB PASSIM","OUT OF TOWN","THE PIT"],"note":"Club Passim is where Joan Baez played as a teenager. The Out of Town News kiosk sold papers from everywhere until 2019 and the shell is still there."},{"name":"___ SQUARE","colour":"p","tiles":["HARVARD","CENTRAL","INMAN","UNION"],"note":"Cambridge is organised entirely into squares, almost none of which are square."}],"epilogue":"PORTER and KENDALL would each have fitted both the station group and the square group, so neither is on this board — that is how a puzzle stays solvable. DAVIS is the one that got in, and ALEWIFE, ASHMONT and BRAINTREE keep it honest."},
{"id":2,"title":"The Yard","diff":2,"groups":[{"name":"HARVARD HOUSES","colour":"y","tiles":["ADAMS","LOWELL","ELIOT","KIRKLAND"],"note":"Twelve upperclass houses, assigned by lottery on Housing Day, and residents will argue about the ranking until they die."},{"name":"HARVARD GRADUATE SCHOOLS","colour":"g","tiles":["LAW","DESIGN","DIVINITY","KENNEDY"],"note":"The Divinity School is the oldest non-sectarian divinity school in the United States; the Kennedy School is across the river and knows it."},{"name":"IN HARVARD YARD","colour":"b","tiles":["WIDENER","JOHN HARVARD","MASS HALL","SEVER"],"note":"The statue is called the Statue of Three Lies: it isn't John Harvard, he didn't found the college, and the date is wrong."},{"name":"___ YARD","colour":"p","tiles":["SCOTLAND","JUNK","BACK","GRAVE"],"note":"Scotland Yard, junkyard, backyard, graveyard. Only one of them has a tourist problem."}],"epilogue":"The difficulty is knowing that Massachusetts Hall is a building and not a school, and that Sever is a lecture hall and not a house. KENNEDY reads like a house because the houses are all named after men; the four houses were already full. Widener holds about 3.5 million volumes and is named for a man who died on the Titanic."},
{"id":3,"title":"02138","diff":3,"groups":[{"name":"CAMBRIDGE STREETS","colour":"y","tiles":["BRATTLE","MASS AVE","GARDEN","DUNSTER"],"note":"Brattle Street was Tory Row before the Revolution; the loyalists' houses are still standing and now hold seminars."},{"name":"MIT THINGS","colour":"g","tiles":["THE DOME","THE INFINITE","HACKS","STATA CENTER"],"note":"The Infinite Corridor is 251 m long and twice a year the sun lines up down the whole thing — MIThenge. The hacks have put a police car and a fire truck on the Dome."},{"name":"CAMBRIDGE FOOD LANDMARKS","colour":"b","tiles":["MR BARTLEY'S","TOSCANINI'S","DARWIN'S","FLOUR"],"note":"Bartley's has named a burger after every politician since the 1960s; Toscanini's ice cream was called the best in the world by the New York Times."},{"name":"BOSTON ___","colour":"p","tiles":["CREAM PIE","TERRIER","MARATHON","TEA PARTY"],"note":"Boston cream pie is a cake, the Boston terrier is the state dog, and the marathon has been run on Patriots' Day since 1897."}],"epilogue":"Two tiles are pointing at the wrong group and neither can move: THE DOME, THE INFINITE, HACKS and STATA CENTER are one campus with no vacancies, and CREAM PIE, TERRIER, MARATHON and TEA PARTY are a full set of Bostons. Mass Ave merely goes past MIT, and the Garden is spelt the same as a street off Cambridge Common."},
{"id":4,"title":"Head of the Charles","diff":4,"groups":[{"name":"ROWING WORDS","colour":"y","tiles":["COXSWAIN","ERG","REGATTA","SHELL"],"note":"The Head of the Charles is the largest three-day regatta in the world, about 11,000 athletes every October, and the Weeks Bridge turn is where races are won and lost."},{"name":"STREETS OFF HARVARD SQUARE","colour":"g","tiles":["JFK STREET","BOW STREET","PLYMPTON","HOLYOKE"],"note":"JFK Street was Boylston Street until 1981. Plympton holds the Grolier Poetry Book Shop, open since 1927 and selling nothing but poetry."},{"name":"VERY MASSACHUSETTS NOUNS","colour":"b","tiles":["PACKIE","ROTARY","JIMMIES","FRAPPE"],"note":"Liquor store, roundabout, sprinkles, and a milkshake with ice cream in it — order a 'milkshake' here and you get milk shaken with syrup."},{"name":"PLACE NAMES FROM ALGONQUIAN LANGUAGES","colour":"p","tiles":["NANTUCKET","SWAMPSCOTT","MATTAPAN","SAUGUS"],"note":"Massachusetts itself is Algonquian — roughly 'at the great hill' — as are Mystic, Neponset, Cochituate and about half the map."}],"epilogue":"Sixteen tiles that are mostly either an odd noun or a place name, which is the whole difficulty. COXSWAIN, ERG, REGATTA and SHELL are already a full crew and NANTUCKET, SWAMPSCOTT, MATTAPAN and SAUGUS are already a full map, so the bow stays on land and Holyoke stays English."},
{"id":5,"title":"Zone 1","diff":2,"groups":[{"name":"LINES ON THE UNDERGROUND","colour":"y","tiles":["BAKERLOO","JUBILEE","CENTRAL","DISTRICT"],"note":"Bakerloo is a 1906 newspaper contraction of Baker Street & Waterloo, and the Metropolitan's proprietor called it a piece of gutter journalism."},{"name":"LONDON BOROUGHS","colour":"g","tiles":["HACKNEY","ISLINGTON","LAMBETH","SOUTHWARK"],"note":"Thirty-two boroughs plus the City, which is not one. Southwark was London's disreputable overflow for centuries because it sat outside the City's jurisdiction."},{"name":"LONDON MARKETS","colour":"b","tiles":["BOROUGH","BRICK LANE","PORTOBELLO","COLUMBIA ROAD"],"note":"Borough has been trading in some form since the 12th century; Columbia Road is flowers only, on Sundays only, and shouted at you from 8 a.m."},{"name":"___ CROSS","colour":"p","tiles":["KING'S","CHARING","RED","DOUBLE"],"note":"King's Cross, Charing Cross, Red Cross, double-cross. Charing Cross is the point every road sign in Britain measures 'London' from."}],"epilogue":"The joke is that BOROUGH is the generic word for the group above it, a neighbourhood, a station and a market — four jobs, one tile. HACKNEY, ISLINGTON, LAMBETH and SOUTHWARK are already four boroughs, so the market keeps its fourth stall."},
{"id":6,"title":"Mind the Gap","diff":3,"groups":[{"name":"HEARD ON THE UNDERGROUND","colour":"y","tiles":["MIND THE GAP","STAND CLEAR","TOUCH IN","SEE IT SAY IT"],"note":"'Mind the gap' was recorded in 1968 because the curve at Embankment left a genuinely dangerous space. The original voice was restored to that platform in 2013 at the request of the announcer's widow."},{"name":"LONDON PUB NAMES","colour":"g","tiles":["RED LION","ROYAL OAK","THE CROWN","THE SHIP"],"note":"Red Lion is the commonest pub name in the country and Royal Oak commemorates a king hiding in a tree, which is a very British reason to name a building."},{"name":"LONDON GREEN SPACES","colour":"b","tiles":["THE HEATH","CLAPHAM COMMON","KEW GARDENS","VICTORIA PARK"],"note":"Hampstead Heath is 320 hectares of deliberately unmown London; Victoria Park in the East End was the first park built specifically for the public, in 1845."},{"name":"COCKNEY RHYMING SLANG","colour":"p","tiles":["DOG AND BONE","PLATES OF MEAT","BOAT RACE","PORKIES"],"note":"Phone, feet, face, and lies — porkies from pork pies. The good ones drop the rhyming half entirely, which is why nobody can follow them."}],"epilogue":"Two of the four groups are things you hear rather than see, which is the board's real trick. THE HEATH, CLAPHAM COMMON, KEW GARDENS and VICTORIA PARK cannot be anything else, and neither can MIND THE GAP, STAND CLEAR, TOUCH IN and SEE IT SAY IT — so the pub keeps its crown and the boat race stays a face."},
{"id":7,"title":"The Knowledge","diff":4,"groups":[{"name":"LONDON RAIL TERMINI","colour":"y","tiles":["PADDINGTON","EUSTON","WATERLOO","ST PANCRAS"],"note":"Fourteen terminus stations, more than any city on earth, because the Victorian railway companies were forbidden from tunnelling into the middle and all stopped at the edge."},{"name":"BRIDGES OVER THE THAMES","colour":"g","tiles":["TOWER","MILLENNIUM","ALBERT","CHELSEA"],"note":"The Millennium wobbled so badly on its opening weekend in 2000 that it shut for two years; Albert Bridge still carries a sign asking troops to break step."},{"name":"LONDON FOOD, PROPERLY LONDON","colour":"b","tiles":["PIE AND MASH","JELLIED EELS","FULL ENGLISH","BEIGEL"],"note":"Eels were the cheap protein of the tidal Thames, and the Brick Lane beigel shops — spelt that way, boiled not baked — have not shut since the 1970s."},{"name":"___ GARDEN","colour":"p","tiles":["COVENT","KITCHEN","BEER","WINTER"],"note":"Covent Garden was a convent garden. The other three are places to grow food, drink beer and keep plants alive through February."}],"epilogue":"WATERLOO is the double agent and it loses on arithmetic: TOWER, MILLENNIUM, ALBERT and CHELSEA are already four bridges and cannot spare a place. If you tried to make a station group out of BEIGEL, that is a Brick Lane problem, not a puzzle problem."},
{"id":8,"title":"The Great","diff":5,"groups":[{"name":"LOST RIVERS OF LONDON","colour":"y","tiles":["FLEET","TYBURN","WESTBOURNE","EFFRA"],"note":"All four still run, in pipes: the Fleet under Farringdon Road, the Westbourne through a metal tube above the platforms at Sloane Square, where you can watch it go by."},{"name":"STREETS IN THE SQUARE MILE","colour":"g","tiles":["THREADNEEDLE","CHEAPSIDE","POULTRY","BREAD STREET"],"note":"The City's streets are a medieval shopping list — Poultry, Bread Street, Milk Street, Honey Lane — and Cheapside is from 'ceap', to barter, not from cheap."},{"name":"LONDON'S OLD PRISONS","colour":"b","tiles":["NEWGATE","MARSHALSEA","THE CLINK","BRIDEWELL"],"note":"Dickens's father was in the Marshalsea for debt, which is most of Little Dorrit. The Clink gave English 'in the clink' and Bridewell gave it a word for a whole class of prison."},{"name":"PRECEDED BY 'THE GREAT'","colour":"p","tiles":["FIRE","PLAGUE","STINK","SMOG"],"note":"1666, 1665, 1858 and 1952. The Great Stink got the Thames embanked and sewered; the Great Smog killed thousands in five days and produced the Clean Air Act."}],"epilogue":"The hardest board in the pack: three tiles are pointing at the punishment group and the punishment group is full. FLEET and TYBURN are water before they are gallows, and NEWGATE is a prison before it is a postcode — the rivers only resolve because a river group of two is not a group."},
{"id":9,"title":"Auld Reekie","diff":2,"groups":[{"name":"HILLS IN EDINBURGH","colour":"y","tiles":["ARTHUR'S SEAT","CALTON HILL","BLACKFORD HILL","CORSTORPHINE"],"note":"Arthur's Seat is the plug of a volcano that stopped erupting about 340 million years ago and is now climbed by people in office shoes on their lunch break."},{"name":"CLOSES OFF THE ROYAL MILE","colour":"g","tiles":["MARY KING'S","ADVOCATE'S","ANCHOR","WORLD'S END"],"note":"Mary King's Close was built over, not demolished, so it is still down there under the City Chambers. World's End sat at the old city wall — beyond it you were nobody's problem."},{"name":"EDINBURGH FESTIVALS","colour":"b","tiles":["FRINGE","HOGMANAY","BELTANE","THE TATTOO"],"note":"The Fringe began in 1947 as eight companies who were not invited to the official festival and turned up anyway. Beltane is a fire ceremony revived in 1988 on Calton Hill."},{"name":"SCOTS WORDS FOR A LANE","colour":"p","tiles":["WYND","BRAE","PEND","VENNEL"],"note":"A wynd is a narrow through-route, a brae is a slope, a pend is an arched passage under a building, and a vennel runs between two buildings."}],"epilogue":"CLOSE is deliberately not on this board: it is both a Royal Mile close and the fifth Scots word for a lane, and one tile cannot sit in two groups. FRINGE, HOGMANAY, BELTANE and THE TATTOO are already four festivals, so Calton Hill stays geology."},
{"id":10,"title":"The Shore","diff":3,"groups":[{"name":"LEITH LANDMARKS","colour":"y","tiles":["THE SHORE","LEITH WALK","OCEAN TERMINAL","BRITANNIA"],"note":"The royal yacht has been moored at Ocean Terminal since 1998, which means Leith's biggest tourist attraction is a decommissioned boat with the Queen's writing desk on it."},{"name":"WATER IN EDINBURGH","colour":"g","tiles":["WATER OF LEITH","UNION CANAL","THE FORTH","DUDDINGSTON"],"note":"The Water of Leith runs 35 km from the Pentlands to the docks; the Union Canal ends in the middle of Fountainbridge and once carried coal to Glasgow."},{"name":"TRAINSPOTTING CHARACTERS","colour":"b","tiles":["RENTON","SICK BOY","SPUD","BEGBIE"],"note":"Irvine Welsh set it in Leith when Leith was the poorest part of the city. The opening monologue was filmed on Princes Street and the rest mostly in Glasgow."},{"name":"SCOTS WEATHER WORDS","colour":"p","tiles":["DREICH","HAAR","SMIRR","SNELL"],"note":"Dreich is grey and endless, haar is the cold sea fog that swallows the city from the east, smirr is rain too fine to bother with a hood for, and snell is a wind with an edge."}],"epilogue":"Both double-fits lose to the same arithmetic: THE SHORE, LEITH WALK, OCEAN TERMINAL and BRITANNIA are four Leith landmarks with no vacancy, and DREICH, SMIRR and SNELL need a fourth kind of weather. The haar is the most Edinburgh thing on the board and it still has to stay in its box."},
{"id":11,"title":"Marchmont","diff":3,"groups":[{"name":"EDINBURGH STUDENT DISTRICTS","colour":"y","tiles":["MARCHMONT","TOLLCROSS","NEWINGTON","BRUNTSFIELD"],"note":"Marchmont is four storeys of Victorian tenement flats let almost entirely to twenty-two-year-olds, and its bins are a reliable September indicator of the academic calendar."},{"name":"FEATURES OF A TENEMENT FLAT","colour":"g","tiles":["THE STAIR","DRYING GREEN","BOX ROOM","BAY WINDOW"],"note":"The stair is the shared stone staircase and also the social unit — a stair has a rota, a smell, and opinions. The drying green is the communal grass nobody's washing ever dries on."},{"name":"EDINBURGH PUBS AND VENUES","colour":"b","tiles":["SANDY BELL'S","THE PEAR TREE","SNEAKY PETE'S","BONGO CLUB"],"note":"Sandy Bell's has had live traditional music nightly since the 1940s; Sneaky Pete's holds about a hundred people and books bands two years before anyone has heard of them."},{"name":"SCOTS FOR EVERYDAY THINGS","colour":"p","tiles":["MESSAGES","BAIRN","KEN","GREET"],"note":"Messages are the groceries, a bairn is a child, ken is know, and to greet is to cry — which is why 'the bairn's greeting' is a sentence and not a riddle."}],"epilogue":"This is the six-years board: a flat, a bin rota, a walk to the pub and four words you only started using because everyone around you did. SANDY BELL'S, SNEAKY PETE'S and BONGO CLUB are three venues that need a fourth, and MARCHMONT, NEWINGTON and BRUNTSFIELD are three addresses that need one too — TOLLCROSS is an address, and the Pear Tree pours pints."},
{"id":12,"title":"The Athens of the North","diff":5,"groups":[{"name":"WRITERS FROM EDINBURGH","colour":"y","tiles":["STEVENSON","MURIEL SPARK","IAN RANKIN","CONAN DOYLE"],"note":"Conan Doyle built Sherlock Holmes out of Joseph Bell, an Edinburgh surgeon who diagnosed strangers for teaching purposes. Rankin's Rebus drinks in the Oxford Bar, which is a real pub."},{"name":"THE SCOTTISH ENLIGHTENMENT","colour":"g","tiles":["HUME","ADAM SMITH","JOSEPH BLACK","HUTTON"],"note":"Hume, Smith, Black and Hutton all knew each other, drank in the same Old Town taverns, and between them produced modern philosophy, economics, chemistry and geology in about forty years."},{"name":"MONUMENTS ON THE SKYLINE","colour":"b","tiles":["NELSON","DUGALD STEWART","THE DISGRACE","SCOTT MONUMENT"],"note":"The Dugald Stewart is the little colonnade in every photograph of the city. The National Monument was left unfinished for lack of money and has been called Edinburgh's Disgrace ever since."},{"name":"WORDS FROM SCOTS LAW","colour":"p","tiles":["PROCURATOR","SHERIFF","ADVOCATE","NOT PROVEN"],"note":"Scotland kept its own legal system in 1707. It has three verdicts, not two, and 'not proven' has the same effect as an acquittal and a completely different flavour."}],"epilogue":"The hardest board in the pack, and the traps point the same way: two tiles are monuments to the sort of person in another group. One word in the blue category is doing all the disambiguating — SKYLINE. There is a statue of Hume on the Royal Mile with a toe rubbed gold by tourists, but it is at street level, so he stays a philosopher. STEVENSON, MURIEL SPARK, IAN RANKIN and CONAN DOYLE are four writers with no room for a spire, and PROCURATOR, SHERIFF, ADVOCATE and NOT PROVEN cannot be anything else — start at the law and work backwards."},
{"id":13,"title":"Inside the Loop","diff":2,"groups":[{"name":"HOUSTON BAYOUS","colour":"y","tiles":["BUFFALO","BRAYS","WHITE OAK","SIMS"],"note":"The city was founded at the head of navigation on Buffalo Bayou, which is the only reason it is where it is. There are about 2,500 miles of the things inside the county."},{"name":"HOUSTON NEIGHBOURHOODS","colour":"g","tiles":["MONTROSE","THE HEIGHTS","THIRD WARD","RIVER OAKS"],"note":"The wards were the original political divisions and the Third Ward is the historic heart of Black Houston. The Heights was a separate city until 1918 and is still dry in places."},{"name":"HOUSTON FREEWAYS","colour":"b","tiles":["KATY FREEWAY","BELTWAY 8","THE 610 LOOP","GULF FREEWAY"],"note":"The Katy Freeway is up to 26 lanes wide, which makes it the widest motorway in the world and, according to every study of it, no faster than before."},{"name":"NICKNAMES FOR HOUSTON","colour":"p","tiles":["SPACE CITY","H-TOWN","CLUTCH CITY","BAYOU CITY"],"note":"Clutch City was a newspaper's apology: the paper had run 'Choke City' during the 1994 play-offs and the Rockets went on to win the title."}],"epilogue":"Every group here is a way of saying where you are from. BUFFALO, BRAYS, WHITE OAK and SIMS are four bayous and cannot spare one for the nickname, and SPACE CITY, H-TOWN and CLUTCH CITY need a fourth — so the Loop stays tarmac and Bayou City stays a nickname."},
{"id":14,"title":"Y'all Means All","diff":3,"groups":[{"name":"TEX-MEX ON THE TABLE","colour":"y","tiles":["QUESO","FAJITAS","MIGAS","BREAKFAST TACO"],"note":"Fajitas were popularised at Ninfa's on Navigation in 1973 from a cut nobody wanted, and the breakfast taco is a load-bearing part of the Houston working day."},{"name":"HOUSTON FOOD INSTITUTIONS","colour":"g","tiles":["WHATABURGER","SHIPLEY'S","FRENCHY'S","NINFA'S"],"note":"Frenchy's Creole fried chicken has fed the Third Ward since 1969 and the Astros' clubhouse for most of that; Shipley's does not glaze a doughnut, it lacquers one."},{"name":"THE VOCABULARY OF BRISKET","colour":"b","tiles":["THE BARK","SMOKE RING","MOIST OR LEAN","BUTCHER PAPER"],"note":"You are asked moist or lean, never fatty or dry. The pink smoke ring is a chemical reaction about a centimetre deep and proves nothing, which does not stop anyone measuring it."},{"name":"BOUGHT AT A TEXAS GAS STATION","colour":"p","tiles":["KOLACHE","BUC-EE'S","BIG RED","BEEF JERKY"],"note":"The kolache is Czech, brought by 19th-century settlers to central Texas, and has been quietly filled with sausage. Big Red tastes like liquid bubblegum and is beloved without apology."}],"epilogue":"Two tiles are trying to get into the institutions group and it is full: WHATABURGER, SHIPLEY'S, FRENCHY'S and NINFA'S are four places with names on the door. The Viet-Cajun crawfish boil is the one great Houston hybrid this board could not fit, which is what an epilogue is for."},
{"id":15,"title":"Mission Control","diff":3,"groups":[{"name":"HOUSTON SPORTING LEGENDS","colour":"y","tiles":["HAKEEM","BIGGIO","EARL CAMPBELL","SIMONE BILES"],"note":"Hakeem Olajuwon arrived from Lagos via the University of Houston and never left; Biles trains north of the city and is the most decorated gymnast in history."},{"name":"HOUSTON RAP","colour":"g","tiles":["DJ SCREW","UGK","GETO BOYS","PAUL WALL"],"note":"DJ Screw slowed records to a crawl on mixtapes sold out of a house in South Park, and thirty years later half of American rap is still moving at his tempo."},{"name":"MISSION CONTROL VOCABULARY","colour":"b","tiles":["NOMINAL","GO/NO-GO","THE TRENCH","CAPCOM"],"note":"'Nominal' means exactly as predicted. The Trench is the front row of consoles that flies the vehicle, and CAPCOM is the one astronaut allowed to talk to the crew."},{"name":"HOUSTON CAR CULTURE","colour":"p","tiles":["SLAB","SWANGAS","CANDY PAINT","CHOPPED"],"note":"SLAB is Slow, Loud And Bangin'. Swangas are the wire rims that stick out a foot, candy paint is the deep lacquer, and the boot is open so you can hear what is in it."}],"epilogue":"Four completely different Houstons on one board — the arena, the mixtape, the console and the parking lot — and they overlap because the city does. HAKEEM, BIGGIO, EARL CAMPBELL and SIMONE BILES are four people, DJ SCREW, UGK, GETO BOYS and PAUL WALL are four acts, and that closes both doors."},
{"id":16,"title":"No Zoning","diff":4,"groups":[{"name":"HOUSTON ART AND ODDITIES","colour":"y","tiles":["THE MENIL","ROTHKO CHAPEL","BEER CAN HOUSE","ORANGE SHOW"],"note":"The Menil is free, always has been, and Renzo Piano lit it with the roof. The Beer Can House is clad in about 50,000 flattened cans by a retired upholsterer with time on his hands."},{"name":"HURRICANES AND STORMS THAT HIT","colour":"g","tiles":["HARVEY","IKE","ALLISON","RITA"],"note":"Harvey dropped more than 60 inches of rain in 2017, the most from any storm in US history. Allison was only a tropical storm and still flooded the Medical Center's basements."},{"name":"HOUSTON SUBURBS","colour":"b","tiles":["KATY","SUGAR LAND","PEARLAND","THE WOODLANDS"],"note":"Sugar Land was a company town for Imperial Sugar and The Woodlands is a master-planned forest with 120,000 people in it. Katy is where the freeway got its name."},{"name":"SAID ONLY IN HOUSTON","colour":"p","tiles":["FEEDER ROAD","THE LOOP","ICEHOUSE","OZONE DAY"],"note":"A feeder road is the frontage road, an icehouse is an open-air bar that started as somewhere selling cold beer, and an ozone action day is the city asking you not to mow the lawn."}],"epilogue":"A city with no zoning code puts a chapel next to a car park and a suburb inside a hurricane track, which is why this board refuses to sort by type. FEEDER ROAD, THE LOOP, ICEHOUSE and OZONE DAY are already four things nobody says anywhere else, so the Orange Show stays art and Katy stays a suburb."}
]},
{"id":"ai","name":"THE ALIGNMENT","blurb":"Alignment, evals, compute governance, the labs, the papers, the acronyms.","boards":[
{"id":1,"title":"Frontier","diff":2,"groups":[{"name":"FRONTIER LABS","colour":"y","tiles":["OPENAI","ANTHROPIC","DEEPMIND","XAI"],"note":"DeepMind was a London startup bought by Google in 2014; OpenAI began as a nonprofit; Anthropic was founded in 2021 by people who left OpenAI. Every one of them has a founding story about safety."},{"name":"MODEL FAMILIES","colour":"g","tiles":["CLAUDE","GEMINI","LLAMA","QWEN"],"note":"Claude is named for Claude Shannon, Llama is Meta's open-weights line, and Qwen is Alibaba's — which is why so much of the open ecosystem now speaks Mandarin upstream."},{"name":"SAFETY-FOCUSED ORGANISATIONS","colour":"b","tiles":["METR","APOLLO","REDWOOD","MIRI"],"note":"METR runs autonomy evaluations on frontier models before release, Apollo works on deception and scheming, Redwood on control, and MIRI has been arguing about all of it since 2000."},{"name":"___ MODEL","colour":"p","tiles":["WORLD","REWARD","FOUNDATION","LANGUAGE"],"note":"World model, reward model, foundation model, language model. Four completely different objects and one very tired noun."}],"epilogue":"The calibration board. The trick is that three of the four groups are proper nouns and the fourth is four ordinary words, so the work is deciding which proper nouns are companies, which are products, and which are the people watching. METR, APOLLO, REDWOOD and MIRI are four already, so Anthropic stays a lab."},
{"id":2,"title":"Acronym Soup","diff":3,"groups":[{"name":"BENCHMARKS","colour":"y","tiles":["MMLU","GPQA","SWE-BENCH","ARC-AGI"],"note":"MMLU is 57 subjects of multiple choice, GPQA is questions PhDs get wrong, SWE-bench is real GitHub issues, and ARC-AGI is deliberately easy for humans and hard for models."},{"name":"STAGES OF TRAINING","colour":"g","tiles":["PRETRAINING","SFT","RLHF","DISTILLATION"],"note":"Pretrain on everything, supervise-fine-tune on demonstrations, reinforce from human feedback, then distil the result into something small enough to serve."},{"name":"POLICY INSTRUMENTS","colour":"b","tiles":["EU AI ACT","SB 1047","EXPORT CONTROL","EXEC ORDER"],"note":"The EU AI Act passed in 2024; California's SB 1047 was vetoed in September 2024; the 2023 US executive order was rescinded in January 2025. Two of these lost and are still instruments."},{"name":"THINGS YOU COUNT WHEN TRAINING","colour":"p","tiles":["FLOPS","TOKENS","PARAMETERS","EPOCHS"],"note":"Chinchilla's finding was that most large models had been counting parameters when they should have been counting tokens — roughly twenty tokens per parameter."}],"epilogue":"Three of these groups are made of acronyms and the fourth is made of units, which is the whole difficulty — the shape of the tile tells you nothing. FLOPS is the honest double-fit: a measurement that became a law. MMLU, GPQA, SWE-BENCH and ARC-AGI are four tests already, so SFT goes back to being training."},
{"id":3,"title":"The Hard Problem","diff":3,"groups":[{"name":"ALIGNMENT FAILURE MODES","colour":"y","tiles":["REWARD HACKING","SYCOPHANCY","DECEPTION","SANDBAGGING"],"note":"Sandbagging is a model doing worse on purpose — which, if a model knows it is being evaluated, makes the evaluation the thing being gamed."},{"name":"INTERPRETABILITY","colour":"g","tiles":["PROBES","SAE","FEATURES","CIRCUITS"],"note":"A sparse autoencoder pulls a layer apart into features that are individually meaningful, on the theory that the model is storing far more concepts than it has neurons."},{"name":"SAFETY TRAINING TECHNIQUES","colour":"b","tiles":["CONSTITUTION","RED TEAMING","DEBATE","RLAIF"],"note":"A constitution is a written set of principles a model critiques itself against; RLAIF replaces the human rater with a model; debate pits two copies against each other in front of a judge."},{"name":"WORDS ALIGNMENT TOOK FROM ECONOMICS","colour":"p","tiles":["PRINCIPAL","AGENT","INCENTIVE","GOODHART"],"note":"The principal–agent problem is 1970s economics and describes this situation exactly. Goodhart was a Bank of England adviser: when a measure becomes a target, it stops being a good measure."}],"epilogue":"The board is four ways of talking about the same worry: what the thing is actually optimising. GOODHART is the trap worth admiring — the man's law describes the yellow group better than any tile in it, and REWARD HACKING, SYCOPHANCY, DECEPTION and SANDBAGGING are already four. PRINCIPAL, AGENT and INCENTIVE need their economist."},
{"id":4,"title":"Zoo","diff":4,"groups":[{"name":"MILESTONE SYSTEMS","colour":"y","tiles":["ALEXNET","ALPHAGO","ALPHAFOLD","GPT-3"],"note":"AlexNet won ImageNet in 2012 and started all of this; AlphaGo beat Lee Sedol in 2016; AlphaFold won a Nobel prize in chemistry in 2024; GPT-3 in 2020 was the one that made scale look like the whole answer."},{"name":"PAPERS PEOPLE NAME-DROP","colour":"g","tiles":["PARROTS","CHINCHILLA","SPARKS OF AGI","SCALING LAWS"],"note":"'On the Dangers of Stochastic Parrots' (2021) got its lead author fired from Google; Chinchilla (2022) rewrote how everyone allocates compute; 'Sparks of AGI' (2023) started an argument that has not finished."},{"name":"AI THOUGHT EXPERIMENTS","colour":"b","tiles":["PAPERCLIPS","CHINESE ROOM","TURING TEST","STOP BUTTON"],"note":"The paperclip maximiser is Bostrom's, the Chinese Room is Searle's objection to the whole project, and the stop-button problem is why 'just switch it off' is not a plan."},{"name":"FINE-TUNES NAMED AFTER A SOUTH AMERICAN CAMELID","colour":"p","tiles":["LLAMA","ALPACA","VICUNA","GUANACO"],"note":"Stanford's Alpaca, LMSYS's Vicuna and QLoRA's Guanaco all came out within months of Llama in 2023. There are exactly four camelids in South America and the field used all of them."}],"epilogue":"Half this board is animals and only four of them are the group. CHINCHILLA and PARROTS are both papers wearing fur, and they cannot move because LLAMA, ALPACA, VICUNA and GUANACO are the complete list of camelids — the field ran out of species, which is why the 2023 model names got weird."},
{"id":5,"title":"Compute","diff":3,"groups":[{"name":"HARDWARE IN A TRAINING RUN","colour":"y","tiles":["H100","TPU","HBM","NVLINK"],"note":"High-bandwidth memory is stacked DRAM sitting next to the die, and it is the part that is actually scarce — the logic is easier to make than the memory bolted to it."},{"name":"THE CHIP SUPPLY CHAIN","colour":"g","tiles":["NVIDIA","TSMC","ASML","SK HYNIX"],"note":"One Dutch company makes the EUV lithography machines, one Taiwanese company makes the leading-edge chips, and that is the whole bottleneck of the modern world in two sentences."},{"name":"LEVERS IN COMPUTE GOVERNANCE","colour":"b","tiles":["EXPORT RULES","COMPUTE CAPS","CHIP TRACKING","CLOUD KYC"],"note":"Compute is the one input to frontier AI that is physical, countable and made in very few places, which is why governance keeps reaching for it instead of for the software."},{"name":"WHAT A DATA CENTRE ACTUALLY NEEDS","colour":"p","tiles":["POWER","WATER","LAND","PERMITS"],"note":"The binding constraint on frontier training moved from chips to gigawatts somewhere around 2025, and the queue to connect to a grid is now measured in years."}],"epilogue":"Two tiles are pointing one group down the board and neither can move: NVIDIA, TSMC, ASML and SK HYNIX are a full supply chain, and EXPORT RULES, COMPUTE CAPS, CHIP TRACKING and CLOUD KYC are four levers already. The purple is the easiest group to say and the hardest to see — nobody thinks about water until the town meeting."},
{"id":6,"title":"Evals","diff":4,"groups":[{"name":"EVALUATION VOCABULARY","colour":"y","tiles":["ELICITATION","SCAFFOLDING","PASS AT K","HOLDOUT"],"note":"Elicitation is how hard you tried to make the model succeed, and it is the reason two labs can run the same eval on the same model and disagree by twenty points."},{"name":"DANGEROUS-CAPABILITY DOMAINS","colour":"g","tiles":["CYBER","BIO","PERSUASION","AUTONOMY"],"note":"These four are the standard quartet in every frontier safety framework, and autonomy is the one that changed fastest between 2024 and 2026."},{"name":"WAYS A BENCHMARK DIES","colour":"b","tiles":["CONTAMINATION","SATURATION","CHERRY-PICKING","LEAKAGE"],"note":"Saturation is when everyone scores 92% and the test stops carrying information; contamination is when the test was in the training data, which is nearly always, a little."},{"name":"___ SET","colour":"p","tiles":["TRAINING","TEST","MIND","TEA"],"note":"Training set, test set, mindset, tea set. Two of them are the reason the other groups exist and two of them are in the cupboard."}],"epilogue":"An eval board that is mostly about how evals fail, which is the honest version. HOLDOUT is the double-fit and it loses because TRAINING, TEST, MIND and TEA are already a full shelf — and because CONTAMINATION, SATURATION and CHERRY-PICKING are three deaths looking for a fourth."},
{"id":7,"title":"The Institutes","diff":3,"groups":[{"name":"STATE AI BODIES","colour":"y","tiles":["AISI","CAISI","EU AI OFFICE","NIST"],"note":"Britain's AI Safety Institute became the AI Security Institute in February 2025; America's became the Center for AI Standards and Innovation, CAISI, that June. Both kept the building and changed the noun."},{"name":"WHERE THE AI SUMMITS HAPPENED","colour":"g","tiles":["BLETCHLEY","SEOUL","PARIS","NEW DELHI"],"note":"Bletchley Park in November 2023 produced a declaration signed by both the US and China; Seoul added commitments; Paris renamed the whole series an Action Summit; India took the fourth."},{"name":"WHAT A LAB PUBLISHES BEFORE IT SCALES","colour":"b","tiles":["RSP","PREPAREDNESS","FSF","MODEL CARD"],"note":"Anthropic's Responsible Scaling Policy, OpenAI's Preparedness Framework, Google DeepMind's Frontier Safety Framework — three documents that promise what a lab will do at a capability level it has not reached yet."},{"name":"PRECEDED BY RED","colour":"p","tiles":["TEAM","LINE","FLAG","TAPE"],"note":"Red team, red line, red flag, red tape. Four things this entire field argues about, and the only group on the board that a lawyer and an engineer would read identically."}],"epilogue":"Two groups of proper nouns, one of documents, one of ordinary words, and the difficulty is that the documents are named after the institutions and the institutions are named after the cities. RSP, PREPAREDNESS, FSF and MODEL CARD are four publications already, which is what keeps NIST an agency and SEOUL a place."},
{"id":8,"title":"Open Weights","diff":3,"groups":[{"name":"OPEN-WEIGHT MODEL FAMILIES","colour":"y","tiles":["MISTRAL","DEEPSEEK","GEMMA","OLMO"],"note":"Gemma is Google's, OLMo is the Allen Institute's and ships its training data too, and DeepSeek's releases in early 2025 made the phrase 'compute moat' considerably less popular."},{"name":"WHAT PEOPLE DO TO A DOWNLOADED MODEL","colour":"g","tiles":["FINE-TUNE","QUANTISE","MERGE","LORA"],"note":"Quantising drops the numbers to four bits so the thing runs on a laptop; LoRA trains a small adapter instead of the whole network; merging averages two models' weights and, unreasonably, often works."},{"name":"VOCABULARY OF THE MISUSE DEBATE","colour":"b","tiles":["UPLIFT","MARGINAL RISK","SAFEGUARDS","DUAL USE"],"note":"'Marginal risk' is the load-bearing phrase: the question is never whether a model can help with something dangerous, but whether it helps more than a library and a search engine already do."},{"name":"___ WEIGHT","colour":"p","tiles":["FEATHER","HEAVY","PAPER","OVER"],"note":"Featherweight, heavyweight, paperweight, overweight. The word 'weights' meaning 'the actual numbers in the model' is barely a decade old outside the lab."}],"epilogue":"The board is one argument seen from three sides: what exists, what you can do with it, and what people say about what you can do with it. SAFEGUARDS is the tile with two homes, and it stays in blue because FINE-TUNE, QUANTISE, MERGE and LORA are four verbs already — and because UPLIFT, MARGINAL RISK and DUAL USE are three pieces of jargon with a hole in them."},
{"id":9,"title":"The Papers","diff":4,"groups":[{"name":"LANDMARK PAPERS BY SHORTHAND","colour":"y","tiles":["ATTENTION","RESNET","ADAM","DROPOUT"],"note":"'Attention Is All You Need' (2017), residual connections (2015), the Adam optimiser (2014), dropout (2014). Four papers that between them are cited more than most fields."},{"name":"ARCHITECTURES","colour":"g","tiles":["TRANSFORMER","CNN","LSTM","DIFFUSION"],"note":"The LSTM held the sequence-modelling crown for twenty years and lost it in about eighteen months; diffusion took over images by learning to undo noise."},{"name":"WHERE THE FIELD PUBLISHES","colour":"b","tiles":["ARXIV","NEURIPS","ICML","OPENREVIEW"],"note":"The real publication event is the arXiv preprint; the conference is where you find out who else was working on it. OpenReview means the referee reports are public, which is either brave or cruel."},{"name":"___ HEAD","colour":"p","tiles":["HOT","FIGURE","LETTER","ARROW"],"note":"Hothead, figurehead, letterhead, arrowhead. An attention head is none of these, which is the entire reason this group is here."}],"epilogue":"The paper and the thing the paper introduced are almost never the same word, and this board is entirely about that gap: the Transformer is in the architecture group and the paper that invented it is called ATTENTION. If you tried ATTENTION with HOT, FIGURE and LETTER you were reading the board exactly as intended and were still wrong."},
{"id":10,"title":"Agents","diff":3,"groups":[{"name":"ONE TURN OF AN AGENT LOOP","colour":"y","tiles":["PLAN","ACT","OBSERVE","REFLECT"],"note":"Plan, act, observe, reflect, repeat until done or until the budget runs out. Almost every agent framework since 2023 is a rediscovery of this loop with different logging."},{"name":"HOW AN AGENT GOES WRONG","colour":"g","tiles":["INJECTION","JAILBREAK","LOOPING","EXFILTRATION"],"note":"Prompt injection is the one with no clean fix: if a model reads a web page, the web page gets to talk to it, and instructions and data arrive down the same pipe."},{"name":"AGENT PLUMBING","colour":"b","tiles":["MCP","API","TOOL CALL","SANDBOX"],"note":"The Model Context Protocol was opened up in late 2024 to stop every tool integration being written twice; the sandbox is the part everybody adds after the first incident."},{"name":"___ AGENT","colour":"p","tiles":["FREE","DOUBLE","ESTATE","SECRET"],"note":"Free agent, double agent, estate agent, secret agent. The word arrived in AI from economics, where an agent is simply someone acting on another's behalf."}],"epilogue":"Four groups and only one of them is really about software. SANDBOX is the honest double-fit — you build one, then you spend your life worrying about escapes from it — and INJECTION, JAILBREAK, LOOPING and EXFILTRATION are four ways to fail already. The purple is the reminder that 'agent' was a word about trust long before it was a word about tools."},
{"id":11,"title":"Governance","diff":4,"groups":[{"name":"MACHINERY OF THE EU AI ACT","colour":"y","tiles":["RISK TIERS","GPAI","CE MARKING","ANNEX III"],"note":"Four tiers from unacceptable down to minimal, a separate chapter for general-purpose models, the same CE mark that appears on a kettle, and Annex III — the list that decides what counts as high-risk."},{"name":"RECURRING US AI POLICY FIGHTS","colour":"g","tiles":["PREEMPTION","MORATORIUM","LIABILITY","LICENSING"],"note":"Whether federal rules should override state ones, whether to pause anything, who pays when a model causes harm, and whether training a frontier model should need permission. The same four arguments every session."},{"name":"WHAT A GOVERNANCE REGIME ASKS FOR","colour":"b","tiles":["AUDITS","INCIDENT LOGS","REGISTRATION","WATERMARKS"],"note":"Every regime lands on roughly the same four asks, borrowed wholesale from finance, aviation and food safety — which is why the vocabulary sounds older than the technology."},{"name":"___ CONTROL","colour":"p","tiles":["EXPORT","QUALITY","REMOTE","CROWD"],"note":"Export control, quality control, remote control, crowd control. Only one of them has ever been used to try to slow down a technology on purpose."}],"epilogue":"Three groups of policy vocabulary and one of ordinary compounds, and the trick is that policy vocabulary IS ordinary compounds. EXPORT is the double-fit and it goes purple because PREEMPTION, MORATORIUM, LIABILITY and LICENSING are four live American arguments already — a set that would look completely different if this board had been written in Brussels."},
{"id":12,"title":"The Long Run","diff":5,"groups":[{"name":"WORDS FOR THE THING PEOPLE ARE WORRIED ABOUT","colour":"y","tiles":["X-RISK","S-RISK","TAKEOFF","SINGULARITY"],"note":"Existential risk, suffering risk, the speed of the transition, and the 1993 word for the point past which the graph stops being readable. Three of the four were coined in the same small set of mailing lists."},{"name":"NAMES ATTACHED TO THE ARGUMENT","colour":"g","tiles":["BOSTROM","YUDKOWSKY","HINTON","RUSSELL"],"note":"Bostrom wrote the 2014 book, Yudkowsky spent two decades on the mailing lists, Russell wrote the textbook and then wrote the objection, and Hinton left Google in 2023 to say it out loud."},{"name":"BORROWED FROM SAFETY ENGINEERING","colour":"b","tiles":["SAFETY CASE","SWISS CHEESE","TRIPWIRE","NEAR MISS"],"note":"A safety case is an argument that a system is safe enough, written down and challengeable — nuclear and aviation have required them for decades, which is why AI keeps reaching for the phrase."},{"name":"FIRE ___","colour":"p","tiles":["ALARM","WALL","DRILL","ESCAPE"],"note":"Fire alarm, firewall, fire drill, fire escape. All four have been used as metaphors in this argument, and one of them is the title of the most-quoted essay in it."}],"epilogue":"The hardest board in the pack, and the reason is that this field talks about itself in borrowed words: half the safety vocabulary is aviation, half the risk vocabulary is science fiction, and the surnames are doing the work of citations. TAKEOFF is the double-fit worth the price of admission — and SAFETY CASE, SWISS CHEESE, TRIPWIRE and NEAR MISS are four borrowings already, so the aeroplane stays in yellow."}
]},
{"id":"jewish","name":"DIASPORA","blurb":"Holidays, food, Yiddish and Hebrew in English, texts, music, and Israel.","boards":[
{"id":1,"title":"Friday Night","diff":2,"groups":[{"name":"SHABBAT, START TO FINISH","colour":"y","tiles":["CANDLES","KIDDUSH","CHALLAH","HAVDALAH"],"note":"Two candles to open it, wine and the blessing over it, the braided loaf under its cover — and havdalah, the spice-and-candle ceremony that hands you back to Tuesday."},{"name":"ON AN ASHKENAZI FRIDAY-NIGHT TABLE","colour":"g","tiles":["GEFILTE FISH","CHICKEN SOUP","CHOLENT","KUGEL"],"note":"Cholent is the point: a stew left on a low flame from before sundown, invented entirely so that a hot meal could be eaten on a day when you cannot cook."},{"name":"AMONG THE 39 FORBIDDEN LABOURS","colour":"b","tiles":["KINDLING","WRITING","CARRYING","REAPING"],"note":"The 39 melachot are derived from the building of the Tabernacle, which is why 'reaping' is on a list that also governs whether you may switch on a light."},{"name":"___ TOV","colour":"p","tiles":["MAZEL","SHAVUA","YOM","SIMAN"],"note":"Mazel tov (good luck, said as congratulations), shavua tov (good week, said after havdalah), yom tov (a festival day), siman tov (a good sign — the wedding song)."}],"epilogue":"The whole board is one evening in a house, which is why two tiles look like they are in the wrong room. Both are pinned by arithmetic: GEFILTE FISH, CHICKEN SOUP, CHOLENT and KUGEL are already four courses, and CANDLES, KIDDUSH and HAVDALAH need a fourth that is part of the ritual rather than the meal."},
{"id":2,"title":"The Autumn","diff":3,"groups":[{"name":"THE AUTUMN HOLIDAYS, IN ORDER","colour":"y","tiles":["ROSH HASHANAH","YOM KIPPUR","SUKKOT","SIMCHAT TORAH"],"note":"New year, the day of atonement ten days later, the week in a hut with a roof you can see stars through, and then the dancing when the Torah is rolled back to the beginning."},{"name":"EATEN ON ONE PARTICULAR HOLIDAY","colour":"g","tiles":["HONEY CAKE","LATKES","HAMANTASCHEN","MATZAH"],"note":"Honey cake for a sweet new year, latkes fried in oil for Hanukkah, hamantaschen shaped like a villain's hat for Purim, matzah for the week you own no bread."},{"name":"MONTHS OF THE HEBREW CALENDAR","colour":"b","tiles":["TISHREI","NISAN","ELUL","ADAR"],"note":"A lunar year with a leap month bolted on seven times every nineteen years, which is how Passover stays in spring while the months keep moving."},{"name":"THE MISHNAH SAYS THERE IS A NEW YEAR FOR THESE","colour":"p","tiles":["YEARS","KINGS","CATTLE","TREES"],"note":"Four new years, opening line of Mishnah Rosh Hashanah: the first of Nisan for kings, the first of Elul for tithing animals, the first of Tishrei for years, and Tu BiShvat for trees."}],"epilogue":"The purple is the oldest joke in the calendar: the rabbis counted four separate new years and put them in the first sentence of the tractate about the new year. NISAN is named in that sentence, which is exactly why it cannot leave the month group — TISHREI, ELUL and ADAR need a fourth, and YEARS, KINGS, CATTLE and TREES are already a full set of birthdays."},
{"id":3,"title":"Words You Already Use","diff":3,"groups":[{"name":"YIDDISH VERBS ENGLISH ADOPTED","colour":"y","tiles":["SCHLEP","KVETCH","SCHMOOZE","NOSH"],"note":"Schlepn (to drag), kvetshn (to squeeze — hence to complain), shmuesn (to chat), nashn (to nibble). English took the verbs and left the grammar."},{"name":"YIDDISH FOR A TYPE OF PERSON","colour":"g","tiles":["MENSCH","SCHLEMIEL","NUDNIK","YENTA"],"note":"A mensch is a person you can rely on; a schlemiel spills the soup and a schlimazel is who it lands on; a nudnik asks the schlemiel how the soup was."},{"name":"HEBREW WORDS ENGLISH TOOK, USUALLY VIA THE BIBLE","colour":"b","tiles":["AMEN","JUBILEE","BEHEMOTH","SABBATICAL"],"note":"Amen ('so be it'), yovel (the ram's-horn year of release) into jubilee, b'hemot (beasts) into behemoth, and shabbat into the year off that professors get."},{"name":"___ NIK","colour":"p","tiles":["BEAT","SPUT","REFUSE","KIBBUTZ"],"note":"The -nik suffix arrived in English through Yiddish and Russian together: beatnik and sputnik made it a joke ending, refusenik and kibbutznik made it a political one."}],"epilogue":"Three groups of borrowed words and one group of suffixes, so the sorting question is grammatical: is the tile a verb, a person, or a stem waiting for -NIK? KIBBUTZ is the honest double-fit and it loses because AMEN, JUBILEE, BEHEMOTH and SABBATICAL are four Hebrew imports already, while BEAT, SPUT and REFUSE are three fragments that mean nothing on their own."},
{"id":4,"title":"The Appetizing Store","diff":2,"groups":[{"name":"FROM THE APPETIZING COUNTER","colour":"y","tiles":["LOX","WHITEFISH","SABLE","SCHMEAR"],"note":"An appetizing store sells the things you put on a bagel and a delicatessen sells meat, because kosher rules keep fish and flesh in separate shops — a dietary law that became a retail category."},{"name":"FROM THE DELI COUNTER","colour":"g","tiles":["PASTRAMI","CORNED BEEF","BRISKET","TONGUE"],"note":"Pastrami came to New York with Romanian Jews, corned beef with Irish and Jewish New York at once, and both are the same cut argued about in two accents."},{"name":"FROM THE JEWISH BAKERY","colour":"b","tiles":["BABKA","RUGELACH","BIALY","BAGEL"],"note":"A bialy is a bagel's flatter cousin from Bialystok with onion in the dimple and no boiling step, which is why it goes stale by lunchtime."},{"name":"___ SALT","colour":"p","tiles":["SEA","ROCK","TABLE","KOSHER"],"note":"Kosher salt is not kosher salt — it is koshering salt, the coarse grain used to draw blood out of meat, and the name stuck to the box."}],"epilogue":"Three counters and a box of salt. BAGEL is the tile everyone puts in the wrong shop, and the fix is the one fact this board is built on: fish and meat are sold in different premises, so LOX, WHITEFISH, SABLE and SCHMEAR are a complete counter without it, and BABKA, RUGELACH and BIALY are three-quarters of a bakery waiting."},
{"id":5,"title":"The Map of Everywhere Else","diff":4,"groups":[{"name":"CAPITALS OF THE YIDDISH-SPEAKING WORLD","colour":"y","tiles":["VILNA","WARSAW","ODESSA","LODZ"],"note":"Vilna was called the Jerusalem of Lithuania for its scholars and its printing presses; Odessa was the joke-telling, opera-going, gloriously secular one."},{"name":"SEPHARDI CITIES BEFORE AND AFTER 1492","colour":"g","tiles":["TOLEDO","SALONICA","FEZ","IZMIR"],"note":"Toledo emptied in 1492 and Salonica filled up: by the 19th century the port of Salonica was so Jewish that it closed on Saturdays."},{"name":"WHERE THE MIZRAHI COMMUNITIES CAME FROM","colour":"b","tiles":["BAGHDAD","ALEPPO","SANA'A","TEHRAN"],"note":"Baghdad was roughly a quarter Jewish in the 1920s. Almost all of these communities left between 1948 and 1979, and Tehran's is the largest one still there."},{"name":"NEIGHBOURHOODS WITH A KOSHER HIGH STREET","colour":"p","tiles":["GOLDERS GREEN","STAMFORD HILL","BOROUGH PARK","BROOKLINE"],"note":"Golders Green and Stamford Hill for London, Borough Park for Brooklyn, Brookline for Boston — four places where the bakeries shut early on Friday."}],"epilogue":"Every tile is somewhere people lived, so type tells you nothing and only history sorts it. IZMIR is the genuine double-fit — the labels Sephardi and Mizrahi were invented later and do not cut cleanly through the Ottoman Aegean. It stays put because BAGHDAD, ALEPPO, SANA'A and TEHRAN are four already, and because TOLEDO, SALONICA and FEZ need a fourth port."},
{"id":6,"title":"The Bookshelf","diff":4,"groups":[{"name":"BOOKS OF THE TORAH, IN HEBREW","colour":"y","tiles":["BERESHIT","SHEMOT","VAYIKRA","BAMIDBAR"],"note":"In the beginning, Names, And He Called, In the Wilderness — each book is named for one of its own first few words, then Devarim makes five."},{"name":"THE RABBINIC SHELF","colour":"g","tiles":["MISHNAH","GEMARA","MIDRASH","SHULCHAN ARUCH"],"note":"Mishnah plus Gemara equals Talmud; midrash is the storytelling around the edges; the Shulchan Aruch is Joseph Karo's 16th-century one-volume answer to 'but what do I actually do?'"},{"name":"MEDIEVAL GIANTS","colour":"b","tiles":["RASHI","MAIMONIDES","IBN EZRA","JUDAH HALEVI"],"note":"Rashi in Champagne, Maimonides in Cordoba and then Cairo, Ibn Ezra everywhere, Judah Halevi writing love poems to a city he died trying to reach."},{"name":"THERE ARE TEN OF THESE","colour":"p","tiles":["COMMANDMENTS","PLAGUES","SEFIROT","LOST TRIBES"],"note":"Ten utterances at Sinai, ten plagues in Egypt, ten sefirot in the kabbalistic diagram of everything, and ten tribes that walked off the map after 722 BCE."}],"epilogue":"Two groups of titles, one of authors, one of numbers, and the difficulty is that the authors ARE titles in Jewish shorthand — you say 'the Rashi' meaning the commentary. BERESHIT, SHEMOT, VAYIKRA and BAMIDBAR are four fixed points, so MIDRASH stays on the rabbinic shelf and RASHI stays a person."},
{"id":7,"title":"Klezmer","diff":4,"groups":[{"name":"IN A KLEZMER BAND","colour":"y","tiles":["CLARINET","TSIMBL","ACCORDION","TROMBONE"],"note":"The clarinet does the laughing and crying because it can bend a note the way a voice does; the tsimbl is a hammered dulcimer you carry on a strap."},{"name":"SUNG FROM MEMORY, NO SHEET MUSIC","colour":"g","tiles":["HAVA NAGILA","ADON OLAM","OSEH SHALOM","DAYENU"],"note":"Adon Olam is famously sung to any tune that fits, up to and including football chants, which is how you can hear it at four completely different tempos in one week."},{"name":"JEWISH SONGWRITERS","colour":"b","tiles":["GERSHWIN","LEONARD COHEN","BOB DYLAN","CAROLE KING"],"note":"Gershwin's parents were from Odessa, Cohen came from a rabbinical family in Montreal, Dylan was Zimmerman from Hibbing, and Carole King was Klein from Brooklyn."},{"name":"KLEZMER TUNE FORMS","colour":"p","tiles":["FREYLEKHS","BULGAR","SHER","HORA"],"note":"A freylekhs is the fast happy one, a bulgar the Bessarabian dance that became the standard wedding tempo, a sher a figure dance, a hora the slow limping three-beat — not the Israeli circle dance of the same name."}],"epilogue":"Two groups made of Yiddish words and two made of English, and the trap is the one word that appears in both worlds: HORA is a klezmer tune form here, not the wedding circle. It stays because HAVA NAGILA, ADON OLAM, OSEH SHALOM and DAYENU are four songs already — and because FREYLEKHS, BULGAR and SHER are three forms with a hole in them."},
{"id":8,"title":"Tel Aviv Breakfast","diff":3,"groups":[{"name":"ISRAELI STREET FOOD","colour":"y","tiles":["FALAFEL","SABICH","SHAKSHUKA","MALABI"],"note":"Sabich is fried aubergine, egg and amba in a pita — Iraqi-Jewish home cooking that got out of the house. Malabi is rose-water milk pudding in a plastic cup."},{"name":"ON AN ISRAELI MAP","colour":"g","tiles":["NEGEV","GALILEE","KINNERET","DEAD SEA"],"note":"The Kinneret is the lake everyone else calls Galilee, the Negev is half the country's land and a fraction of its people, and the Dead Sea shoreline drops about a metre a year."},{"name":"HEBREW SLANG","colour":"b","tiles":["SABABA","BALAGAN","YALLA","STAM"],"note":"Sababa (great) and yalla (let's go) are Arabic; balagan (chaos) came through Russian from the Persian balakhaneh, an upper room; stam means 'no reason, just because'."},{"name":"COINED FOR MODERN HEBREW","colour":"p","tiles":["GLIDA","RAKEVET","ITON","MACHSHEV"],"note":"Ice cream, train, newspaper, computer — a revived language needs a word for everything, so a committee built them from biblical roots: machshev is 'thinker', from the root for thought."}],"epilogue":"Two food-and-place groups and two language groups, and the language groups are the fight: modern Hebrew borrowed as hungrily as it invented. SABABA is the tile that could plausibly be either, and it resolves because GLIDA, RAKEVET, ITON and MACHSHEV are four manufactured words with no street in them."},
{"id":9,"title":"1492 and After","diff":4,"groups":[{"name":"NAMES FOR THE COMMUNITIES","colour":"y","tiles":["ASHKENAZI","SEPHARDI","MIZRAHI","ROMANIOTE"],"note":"Ashkenaz is the Rhineland, Sepharad is Spain, mizrach is east — and the Romaniotes were in Greece before any of those labels existed, praying in Greek."},{"name":"JEWISH LANGUAGES","colour":"g","tiles":["YIDDISH","LADINO","JUDEO-ARABIC","JUDEO-PERSIAN"],"note":"The pattern is the same every time: local grammar, Hebrew script, and a layer of Hebrew and Aramaic vocabulary on top. Yiddish is German that way, Ladino is Castilian."},{"name":"WHERE THEY LANDED","colour":"b","tiles":["ELLIS ISLAND","WHITECHAPEL","BUENOS AIRES","JAFFA PORT"],"note":"Two and a half million people left the Russian Empire after 1881; the East End, the Lower East Side, Argentina and the Jaffa quayside were the four doors most of them came through."},{"name":"___ QUARTER","colour":"p","tiles":["JEWISH","ARMENIAN","LATIN","FRENCH"],"note":"Two of these are quarters of Jerusalem's Old City — with the Christian and Muslim quarters making four — and two are neighbourhoods in Paris and New Orleans."}],"epilogue":"A community, a language, a port, a quarter — four ways of answering 'where are you from?' ROMANIOTE genuinely is both a people and a tongue, and the only thing that pins it is counting: YIDDISH, LADINO, JUDEO-ARABIC and JUDEO-PERSIAN are four languages, and ASHKENAZI, SEPHARDI and MIZRAHI are three labels short of a set."},
{"id":10,"title":"A Whole Life","diff":5,"groups":[{"name":"ONE LIFE, IN FOUR CEREMONIES","colour":"y","tiles":["BRIT MILAH","BAT MITZVAH","CHUPPAH","SHIVA"],"note":"Eight days old, twelve or thirteen years old, the wedding canopy, and the week the family sits on low chairs — birth, adulthood, marriage, death, in that order."},{"name":"AT THE WEDDING ITSELF","colour":"g","tiles":["KETUBAH","BADEKEN","THE GLASS","YICHUD"],"note":"The ketubah is the contract, badeken the veiling, the glass is broken so that no joy is ever quite complete, and yichud is the few minutes the couple spend alone afterwards, traditionally to eat."},{"name":"WORDS OF MOURNING","colour":"b","tiles":["KADDISH","YAHRZEIT","SHLOSHIM","UNVEILING"],"note":"Kaddish barely mentions death; yahrzeit is the annual candle; shloshim is the thirty days; the unveiling is when the stone is set, up to a year later."},{"name":"HEBREW LETTERS THAT ARE ALSO 1, 2, 3, 4","colour":"p","tiles":["ALEPH","BET","GIMEL","DALET"],"note":"Every Hebrew letter is a number, which is why the year is written in letters and why gematria is possible at all — and why a Hebrew page number can be read as a word."}],"epilogue":"The hardest board in the pack, because the yellow group is not a category so much as a biography: BRIT MILAH, BAT MITZVAH, CHUPPAH and SHIVA are one person's whole life, and two of those four tiles are also technical terms belonging to the groups either side of them. The purple is the way in — ALEPH, BET, GIMEL and DALET are the only tiles here that are not about an event at all."}
]}
]
};
